


/* ── LAYER 1 · CONTENT (continued) ── */
/* ============ LESSONS 1-10 ============ */
var LESSONS=[
{n:1,t:'Greetings & Introductions',sub:'Hola, Buenos días, Me llamo...',ex:'Spanish greetings are warm and friendly. Use "buenos días" in the morning, "buenas tardes" in the afternoon and "buenas noches" at night. To say your name, say "Me llamo..." (it means "I call myself..."). For a friend say "tú" — for respect say "usted". Start every talk with a greeting, just like Assalam-o-Alaikum at home.',words:[['Hola','Hello','Assalam-o-Alaikum jaisa salam','oh-lah — h is silent','السلام علیکم جیسا سلام'],['Buenos días','Good morning','Subah bakhair','bweh-nos dee-as','صبح بخیر'],['Buenas tardes','Good afternoon','Dopahar bakhair','bweh-nas tar-des','دوپہر بخیر'],['Buenas noches','Good evening / night','Shab bakhair','bweh-nas no-ches','شب بخیر'],['Me llamo...','My name is...','Mera naam ... hai','meh yah-mo — ll sounds like y','میرا نام ...... ہے'],['¿Cómo te llamas?','What is your name?','Aap ka naam kya hai?','koh-mo teh yah-mas','آپ کا نام کیا ہے?'],['Mucho gusto','Pleased to meet you','Mil kar khushi hui','moo-cho goos-to','مل کر خوشی ہوئی'],['¿Cómo estás?','How are you?','Aap kaise hain?','koh-mo es-tas','آپ کیسے ہیں?'],['Estoy bien, gracias','I am well, thanks','Main theek hoon, shukriya','es-toy bee-en gra-see-as','میں ٹھیک ہوں, شکریہ'],['Adiós','Goodbye','Khuda hafiz','ah-dee-os','خدا حافظ'],['Por favor','Please','Meherbani karke','por fah-vor','مہربانی کرکے'],['Gracias','Thank you','Shukriya','gra-see-as','شکریہ']],sents:[['Hola, me llamo Farrakh.','Hello, my name is Farrakh.','Assalam-o-Alaikum, mera naam Farrakh hai.'],['Buenos días. ¿Cómo estás?','Good morning. How are you?','Subah bakhair. Aap kaise hain?'],['Estoy bien, gracias. ¿Y tú?','I am well, thanks. And you?','Main theek hoon, shukriya. Aur aap?']],dlg:[['A','¡Hola! Buenos días.','Hello! Good morning.'],['B','¡Hola! ¿Cómo estás?','Hello! How are you?'],['A','Estoy bien, gracias. Me llamo Farrakh. ¿Y tú?','I am well, thanks. My name is Farrakh. And you?'],['B','Me llamo Sara. ¡Mucho gusto!','My name is Sara. Pleased to meet you!']],quiz:[['What does "Buenos días" mean?',['Good night','Good morning','Thank you','Goodbye'],1,'Buenos días = good morning. Días = days.'],['How do you say "My name is Ahmed"?',['Me llamo Ahmed','Estoy Ahmed','Hola Ahmed','Soy bien Ahmed'],0,'Me llamo... = My name is...'],['What does "Gracias" mean?',['Please','Sorry','Thank you','Hello'],2,'Gracias = thank you. Reply: de nada.'],['"¿Cómo estás?" means...',['What is your name?','How are you?','Where are you?','How much is it?'],1,'Cómo = how, estás = you are.'],['Which greeting fits the night?',['Buenos días','Buenas tardes','Buenas noches','Hola mañana'],2,'Noches = nights → buenas noches at night.']]},
{n:2,t:'Numbers 1–100',sub:'Counting, prices and your age',ex:'Numbers open many doors: prices, time, age, phone numbers. Learn 1–20 well, then the tens: veinte (20), treinta (30), cuarenta (40), cincuenta (50), sesenta (60), setenta (70), ochenta (80), noventa (90), cien (100). Join them with "y" (and): 21 = veintiuno, 35 = treinta y cinco. To say your age use "tengo" + number + "años" — literally "I have 23 years".',words:[['uno, dos, tres','1, 2, 3','Ek, do, teen','oo-no, dos, tres','ایک, دو, تین'],['cuatro, cinco, seis','4, 5, 6','Chaar, paanch, chhe','kwah-tro, seen-ko, seys','چار, پانچ, چھ'],['siete, ocho, nueve, diez','7, 8, 9, 10','Saat, aath, nau, das','see-eh-teh, oh-cho, nweh-veh, dee-es','سات, آٹھ, نو, دس'],['veinte','20','Bees','veyn-teh','بیس'],['treinta y cinco','35','Paintees','treyn-ta ee seen-ko','پینتیس'],['cincuenta','50','Pachaas','seen-kwen-ta','پچاس'],['cien','100','Sau','see-en','سو'],['¿Cuántos años tienes?','How old are you?','Aap ki umar kitni hai?','kwan-tos an-yos tee-eh-nes','آپ کی عمر کتنی ہے?'],['Tengo veintitrés años','I am 23 years old','Meri umar 23 saal hai','ten-go veyn-tee-tres an-yos','میری عمر 23 سال ہے'],['el número de teléfono','phone number','Phone number','noo-meh-ro deh teh-leh-fo-no','فون نمبر'],['mil','1000','Hazaar','meel','ہزار'],['primero, segundo, tercero','first, second, third','Pehla, doosra, teesra','pree-meh-ro, seh-goon-do, ter-seh-ro','پہلا, دوسرا, تیسرا']],sents:[['Tengo veintitrés años.','I am 23 years old.','Meri umar 23 saal hai.'],['Son las tres.','It is three o\'clock.','Teen bajay hain.'],['Cuesta cincuenta.','It costs fifty.','Yeh pachaas ka hai.']],dlg:[['A','¿Cuántos años tienes?','How old are you?'],['B','Tengo veintitrés años. ¿Y tú?','I am 23. And you?'],['A','Tengo veinte años.','I am 20.'],['B','¿Y tu número de teléfono?','And your phone number?'],['A','Es el seis, cero, tres...','It is 6, 0, 3...']],quiz:[['"Siete" means...',['6','7','8','17'],1,'Seis=6, siete=7, ocho=8.'],['How do you say 50?',['cuarenta','cincuenta','sesenta','quince'],1,'50 = cincuenta (like pachaas).'],['"Tengo veinte años" means...',['I have 20 days','I am 20 years old','I want 20','It is 20 o\'clock'],1,'Age uses tengo (I have) + años.'],['35 in Spanish is...',['treinta cinco','treinta y cinco','tres cinco','cincuenta y tres'],1,'Tens + y + unit: treinta y cinco.'],['"Cien" means...',['10','1000','100','20'],2,'Cien = 100, mil = 1000.']]},
{n:3,t:'Days, Months & Time',sub:'¿Qué hora es? — What time is it?',ex:'Days: lunes, martes, miércoles, jueves, viernes, sábado, domingo. Months sound like English: enero, febrero, marzo, abril, mayo, junio, julio, agosto, septiembre, octubre, noviembre, diciembre. Ask the time with "¿Qué hora es?" Answers start with "Es la una" (1 o\'clock) or "Son las..." for other hours. "Mediodía" is noon, "medianoche" is midnight.',words:[['hoy','today','Aaj','oy — h silent','آج'],['mañana','tomorrow','Kal (aane wala)','man-yah-na — ñ = ny','کل (آنے والا)'],['ayer','yesterday','Kal (guzra)','ah-yer','کل (گزرا)'],['el lunes','Monday','Peer','loo-nes','پیر'],['el viernes','Friday','Jumma','vee-er-nes — v like soft b','جمعہ'],['el domingo','Sunday','Itwaar','do-meen-go','اتوار'],['enero','January','January','eh-neh-ro — j sound later','جنوری'],['¿Qué hora es?','What time is it?','Kitne bajay hain?','keh oh-ra es','کتنے بجے ہیں?'],['Son las ocho','It is 8 o\'clock','Aath bajay hain','son las oh-cho','آٹھ بجے ہیں'],['la mañana','morning','Subah','man-yah-na','صبح'],['la noche','night','Raat','no-cheh','رات'],['la semana','week','Hafta','seh-mah-na','ہفتہ']],sents:[['Hoy es viernes.','Today is Friday.','Aaj Jumma hai.'],['Son las dos de la tarde.','It is 2 in the afternoon.','Dopahar ke do bajay hain.'],['Mañana es sábado.','Tomorrow is Saturday.','Kal Hafta hai.']],dlg:[['A','Perdón, ¿qué hora es?','Excuse me, what time is it?'],['B','Son las diez de la mañana.','It is 10 in the morning.'],['A','Gracias. ¿Hoy es lunes?','Thanks. Is today Monday?'],['B','No, hoy es martes.','No, today is Tuesday.']],quiz:[['"Mañana" means...',['Morning only','Tomorrow (and morning)','Night','Yesterday'],1,'Mañana = tomorrow; la mañana = the morning.'],['Friday in Spanish is...',['jueves','viernes','sábado','martes'],1,'Viernes = Friday (Jumma).'],['"¿Qué hora es?" asks...',['What day is it?','What time is it?','Where is it?','How are you?'],1,'Hora = hour/time.'],['1 o\'clock is said as...',['Son las una','Es la una','Son la una','Es las una'],1,'Only 1 uses "Es la una". Others use "Son las...".'],['"Ayer" means...',['Today','Tomorrow','Yesterday','Always'],2,'Ayer = yesterday (guzra kal).']]},
{n:4,t:'Colours & Common Objects',sub:'Red, blue, big, small — describing things',ex:'Colours come after the thing: "un coche rojo" (a red car). Most colours change for girls\' words: rojo/roja, but verde and azul stay the same. Useful size words: grande (big), pequeño (small), nuevo (new), viejo (old). Learn the objects around you: mesa (table), silla (chair), libro (book), puerta (door), móvil (phone).',words:[['rojo','red','Surkh / laal','ro-ho — j = strong kh','سرخ  /  لال'],['azul','blue','Neela','ah-sool','نیلا'],['verde','green','Sabz / hara','ver-deh','سبز  /  ہرا'],['amarillo','yellow','Peela','ah-mah-ree-yo — ll = y','پیلا'],['blanco','white','Safed','blan-ko','سفید'],['negro','black','Kala','neh-gro','کالا'],['la mesa','table','Maiz','meh-sa','میز'],['la silla','chair','Kursi','see-ya — ll = y','کرسی'],['el libro','book','Kitaab','lee-bro','کتاب'],['la puerta','door','Darwaza','pwer-ta','دروازہ'],['el móvil','mobile phone','Mobile','moh-veel','موبائل'],['grande / pequeño','big / small','Bara / chota','gran-deh / peh-ken-yo','بڑا  /  چھوٹا']],sents:[['La mesa es grande.','The table is big.','Maiz bari hai.'],['Quiero una camisa azul.','I want a blue shirt.','Mujhe neeli qameez chahiye.'],['El libro es nuevo.','The book is new.','Kitaab nai hai.']],dlg:[['A','¿De qué color es tu coche?','What colour is your car?'],['B','Es rojo. ¿Y tu móvil?','It is red. And your phone?'],['A','Mi móvil es negro y pequeño.','My phone is black and small.'],['B','¡Muy bonito!','Very nice!']],quiz:[['"Verde" means...',['Blue','Green','Red','White'],1,'Verde = green (sabz).'],['"The book" is...',['la mesa','el libro','la puerta','el móvil'],1,'Libro = book. El for masculine words.'],['Blue shirt (camisa is feminine):',['camisa azul','camisa azula','azul camisa','la azul camisa'],0,'Azul never changes: camisa azul.'],['"Pequeño" means...',['New','Big','Small','Old'],2,'Pequeño = small (chota).'],['"La puerta" means...',['The chair','The table','The door','The phone'],2,'Puerta = door (darwaza).']]},
{n:5,t:'Family & People',sub:'Talking about your family',ex:'Family words: padre (father), madre (mother), hermano (brother), hermana (sister). Change -o to -a for females. "Mi" = my, "tu" = your. "¿Tienes hermanos?" = Do you have brothers/sisters? Answer "Sí, tengo un hermano y una hermana." People words: hombre (man), mujer (woman), niño (boy), niña (girl), amigo (friend).',words:[['la familia','family','Khandan','fah-mee-lee-ah','خاندان'],['el padre','father','Walid','pah-dreh','والد'],['la madre','mother','Walida','mah-dreh','والدہ'],['el hermano','brother','Bhai','er-mah-no — h silent','بھائی'],['la hermana','sister','Behen','er-mah-na','بہن'],['el hijo / la hija','son / daughter','Beta / beti','ee-ho / ee-ha — j = kh','بیٹا  /  بیٹی'],['el abuelo','grandfather','Dada / Nana','ah-bweh-lo','دادا  /  نانا'],['el amigo','friend (male)','Dost','ah-mee-go','دوست'],['el hombre','man','Aadmi','om-breh','آدمی'],['la mujer','woman','Aurat','moo-her — j = kh','عورت'],['¿Tienes hermanos?','Do you have siblings?','Kya aap ke behan bhai hain?','tee-eh-nes er-mah-nos','کیا آپ کے بہن بھائی ہیں?'],['mi familia es grande','my family is big','Mera khandan bara hai','mee fah-mee-lee-ah es gran-deh','میرا خاندان بڑا ہے']],sents:[['Mi padre se llama Ahmed.','My father\'s name is Ahmed.','Mere walid ka naam Ahmed hai.'],['Tengo dos hermanas.','I have two sisters.','Meri do behnein hain.'],['Mi amigo es de Pakistán.','My friend is from Pakistan.','Mera dost Pakistan se hai.']],dlg:[['A','¿Tienes hermanos, Farrakh?','Do you have siblings, Farrakh?'],['B','Sí, tengo un hermano y una hermana.','Yes, I have a brother and a sister.'],['A','¿Cómo se llama tu hermana?','What is your sister\'s name?'],['B','Se llama Aisha.','Her name is Aisha.']],quiz:[['"La madre" means...',['Father','Mother','Sister','Aunt'],1,'Madre = mother (walida).'],['"Brother" in Spanish: ',['hermana','hermano','primo','amigo'],1,'Hermano = brother, hermana = sister.'],['"Mi" means...',['Your','His','My','Our'],2,'Mi = my (mera).'],['"¿Tienes hermanos?" asks...',['Do you have children?','Do you have siblings?','Are you married?','Do you have friends?'],1,'Hermanos = brothers and sisters together.'],['"Woman" is...',['hombre','mujer','niña','señor'],1,'Mujer = woman.']]},
{n:6,t:'Food & Restaurant',sub:'Ordering food like a local',ex:'At a restaurant: first greet, then "¿Tiene un menú?" (Do you have a menu?). Order politely with "Quiero..." (I want...) or "Para mí..." (For me...). At the end: "La cuenta, por favor" (The bill, please). Remember meals: desayuno (breakfast), comida (lunch), cena (dinner). Water is free to ask: "Un vaso de agua, por favor."',words:[['el restaurante','restaurant','Restaurant','res-tow-ran-teh','ریستوران'],['el menú','menu','Menu','meh-noo','مینیو'],['Quiero...','I want...','Mujhe ... chahiye','kee-eh-ro','مجھے ...... چاہیے'],['el pollo','chicken','Murgi','po-yo — ll = y','مرغی'],['el arroz','rice','Chawal','ah-ros — rr rolled','چاول'],['el pan','bread','Roti','pan','روٹی'],['el té','tea','Chai','teh','چائے'],['un vaso de agua','a glass of water','Ek glass paani','oon vah-so deh ah-gwa','ایک گلاس پانی'],['la cuenta, por favor','the bill, please','Bill la dein','kwen-ta por fah-vor','بل لا دیں'],['Tengo hambre','I am hungry','Bhook lagi hai','ten-go am-breh','بھوک لگی ہے'],['Está delicioso','It is delicious','Bohat mazaydar hai','es-ta deh-lee-see-oh-so','بہت مزیدار ہے'],['sin picante','not spicy','Baghair mirch','seen pee-kan-teh','بغیر مرچ']],sents:[['Quiero pollo con arroz, por favor.','I want chicken with rice, please.','Mujhe chicken chawal chahiye.'],['Un té, por favor.','A tea, please.','Ek chai la dein.'],['La cuenta, por favor.','The bill, please.','Bill la dein, meherbani.']],dlg:[['A','Buenas tardes. ¿Tiene un menú?','Good afternoon. Do you have a menu?'],['B','Sí, aquí tiene.','Yes, here you are.'],['A','Para mí, pollo con arroz y un té.','For me, chicken with rice and a tea.'],['B','Muy bien. ¿Algo más?','Very well. Anything else?'],['A','No, gracias. La cuenta después.','No, thanks. The bill later.']],quiz:[['"La cuenta, por favor" means...',['The menu, please','The bill, please','More water','The table, please'],1,'Cuenta = bill/account.'],['"Tengo hambre" means...',['I am thirsty','I am hungry','I am tired','I am cold'],1,'Hambre = hunger. Sed = thirst.'],['Chicken in Spanish: ',['pescado','pollo','carne','arroz'],1,'Pollo = chicken.'],['"Quiero un té" means...',['I want a coffee','I want a tea','I have tea','Tea is here'],1,'Quiero = I want, té = tea (chai).'],['Breakfast is...',['la cena','la comida','el desayuno','el menú'],2,'Desayuno = breakfast (nashta).']]},
{n:7,t:'Ser vs Estar — "To Be"',sub:'Two verbs, one simple rule',ex:'English has one "to be". Spanish has two! SER is for who/what something IS forever: identity, job, place of origin, colour. "Yo soy Farrakh" (I am Farrakh), "Soy de Pakistán" (I am from Pakistan). ESTAR is for how/where things are NOW: feelings, health, location. "Estoy cansado" (I am tired now), "Estoy en casa" (I am at home). Simple memory trick: SER = what it is, ESTAR = how it is.',words:[['soy','I am (ser)','Main hoon (pehchan)','soy','میں ہوں (پہچان)'],['eres','you are (ser)','Tum ho','eh-res','تم ہو'],['es','he/she is (ser)','Woh hai','es','وہ ہے'],['estoy','I am (estar)','Main hoon (halat)','es-toy','میں ہوں (حالت)'],['estás','you are (estar)','Tum ho (halat)','es-tas','تم ہو (حالت)'],['está','he/she is (estar)','Woh hai (halat)','es-ta','وہ ہے (حالت)'],['Soy de Pakistán','I am from Pakistan','Main Pakistan se hoon','soy deh pah-kees-tan','میں پاکستان سے ہوں'],['Estoy cansado','I am tired','Main thaka hua hoon','es-toy kan-sah-do','میں تھکا ہوا ہوں'],['Estoy en casa','I am at home','Main ghar par hoon','es-toy en kah-sa','میں گھر پر ہوں'],['¿Dónde está...?','Where is...?','... kahan hai?','don-deh es-ta','...... کہاں ہے?'],['Es médico','He is a doctor','Woh doctor hai','es meh-dee-ko','وہ ڈاکٹر ہے'],['Está enfermo','He is sick (now)','Woh beemar hai','es-ta en-fer-mo','وہ بیمار ہے']],sents:[['Soy estudiante.','I am a student.','Main student hoon.'],['Estoy contento hoy.','I am happy today.','Main aaj khush hoon.'],['El té está caliente.','The tea is hot.','Chai garam hai.']],dlg:[['A','¿Eres de España?','Are you from Spain?'],['B','No, soy de Pakistán. ¿Y tú?','No, I am from Pakistan. And you?'],['A','Soy de México. ¿Estás cansado?','I am from Mexico. Are you tired?'],['B','Sí, estoy muy cansado hoy.','Yes, I am very tired today.']],quiz:[['"I am Farrakh" (identity) uses...',['estoy','soy','está','es'],1,'Identity = SER → soy.'],['"I am tired" (feeling now) uses...',['soy','eres','estoy','es'],2,'Feelings now = ESTAR → estoy.'],['"She is a teacher" (job) is...',['Está profesora','Es profesora','Estoy profesora','Soy profesora'],1,'Job = SER. She = es.'],['Location "The bank is here": bank ____ aquí.',['es','está','soy','eres'],1,'Location = ESTAR → está.'],['"Soy de Pakistán" means...',['I am in Pakistan','I am from Pakistan','I go to Pakistan','I like Pakistan'],1,'De = from. Soy de... = I am from...']]},
{n:8,t:'Present Tense Regular Verbs',sub:'-ar, -er, -ir verbs made easy',ex:'Most Spanish verbs follow a pattern. Take off the ending: habl-AR (speak), com-ER (eat), viv-IR (live). Then add: yo -o, tú -as/-es, él -a/-e, nosotros -amos/-emos/-imos, ellos -an/-en. So: yo hablo, tú hablas, él habla. Yo como, tú comes. Yo vivo, tú vives. Learn the pattern once and you can use hundreds of verbs!',words:[['hablar','to speak','Bolna','ah-blar','بولنا'],['yo hablo','I speak','Main bolta hoon','yo ah-blo','میں بولتا ہوں'],['comer','to eat','Khana','ko-mer','کھانا'],['nosotros comemos','we eat','Hum khate hain','no-so-tros ko-meh-mos','ہم کھاتے ہیں'],['vivir','to live','Rehna','vee-veer','رہنا'],['ella vive','she lives','Woh rehti hai','eh-ya vee-veh','وہ رہتی ہے'],['trabajar','to work','Kaam karna','tra-bah-har — j = kh','کام کرنا'],['¿Hablas inglés?','Do you speak English?','Kya tum English bolte ho?','ah-blas een-gles','کیا تم انگریزی بولتے ہو?'],['estudiar','to study','Parhna','es-too-dee-ar','پڑھنا'],['beber','to drink','Peena','beh-ber','پینا'],['escribir','to write','Likhna','es-kree-beer','لکھنا'],['ellos trabajan','they work','Woh kaam karte hain','eh-yos tra-bah-han','وہ کام کرتے ہیں']],sents:[['Yo hablo español y urdu.','I speak Spanish and Urdu.','Main Spanish aur Urdu bolta hoon.'],['Comemos pan y té.','We eat bread and tea.','Hum roti aur chai khate/peete hain.'],['Ella vive en Lahore.','She lives in Lahore.','Woh Lahore mein rehti hai.']],dlg:[['A','¿Hablas español?','Do you speak Spanish?'],['B','Sí, hablo un poco. ¿Y tú?','Yes, I speak a little. And you?'],['A','Yo estudio español todos los días.','I study Spanish every day.'],['B','¡Muy bien! Yo también.','Very good! Me too.']],quiz:[['"Yo ____ español" (hablar):',['hablas','habla','hablo','hablan'],2,'Yo form always ends in -o.'],['"We eat" (comer) is...',['comemos','comen','comes','como'],0,'Nosotros + -er verb = -emos.'],['"She lives" (vivir) is...',['vivo','vives','vive','viven'],2,'Él/ella + -ir verb = -e → vive.'],['Which verb means "to drink"?',['comer','beber','leer','ver'],1,'Beber = to drink (peena).'],['"Ellos trabajan" means...',['I work','We work','They work','You work'],2,'Ellos = they, -an ending.']]},
{n:9,t:'Asking Questions',sub:'qué, dónde, cuándo, cuánto...',ex:'Question words: ¿Qué? (what), ¿Quién? (who), ¿Dónde? (where), ¿Cuándo? (when), ¿Por qué? (why), ¿Cómo? (how), ¿Cuánto? (how much/many). Spanish questions wear two marks: ¿ at the start and ? at the end, so you see a question coming! Voice goes up at the end. For yes/no questions just lift your voice: "¿Hablas inglés?"',words:[['¿Qué?','What?','Kya?','keh','کیا?'],['¿Quién?','Who?','Kaun?','kee-en','کون?'],['¿Dónde?','Where?','Kahan?','don-deh','کہاں?'],['¿Cuándo?','When?','Kab?','kwan-do','کب?'],['¿Por qué?','Why?','Kyun?','por keh','کیوں?'],['¿Cómo?','How?','Kaise?','koh-mo','کیسے?'],['¿Cuánto cuesta?','How much does it cost?','Kitne ka hai?','kwan-to kwes-ta','کتنے کا ہے?'],['¿Qué es esto?','What is this?','Yeh kya hai?','keh es es-to','یہ کیا ہے?'],['¿Dónde vives?','Where do you live?','Tum kahan rehte ho?','don-deh vee-ves','تم کہاں رہتے ہو?'],['¿Cuándo es?','When is it?','Yeh kab hai?','kwan-do es','یہ کب ہے?'],['¿Tienes...?','Do you have...?','Kya tumhare paas ... hai?','tee-eh-nes','کیا تمہارے پاس ...... ہے?'],['porque','because','Kyunke','por-keh','کیونکہ']],sents:[['¿Dónde está la estación?','Where is the station?','Station kahan hai?'],['¿Por qué estudias español?','Why do you study Spanish?','Tum Spanish kyun parhte ho?'],['Estudio español porque me gusta.','I study Spanish because I like it.','Main Spanish is liye parhta hoon kyunke mujhe pasand hai.']],dlg:[['A','¿Qué es esto?','What is this?'],['B','Es un libro.','It is a book.'],['A','¿Cuánto cuesta?','How much does it cost?'],['B','Cuesta diez.','It costs ten.']],quiz:[['"Where?" in Spanish: ',['¿Cuándo?','¿Dónde?','¿Quién?','¿Qué?'],1,'Dónde = where (kahan).'],['"¿Cuánto cuesta?" asks...',['Where is it?','What is it?','How much does it cost?','When is it?'],2,'Cuánto = how much, cuesta = costs.'],['"Why?" is...',['porque','¿por qué?','¿cómo?','¿quién?'],1,'¿Por qué? = why. Porque = because.'],['"Who?" is...',['¿Qué?','¿Quién?','¿Cuándo?','¿Cuál?'],1,'Quién = who (kaun).'],['Spanish questions start with...',['!','¿','¡','"'],1,'Upside-down ¿ opens a question.']]},
{n:10,t:'Directions & Travel',sub:'Taxi, hotel, airport — getting around',ex:'Travel Spanish saves you abroad. In a taxi: "A la estación, por favor" (To the station, please). Ask "¿Cuánto cuesta el viaje?" before you sit! Directions: izquierda (left), derecha (right), recto (straight). At a hotel: "Tengo una reserva" (I have a booking), "¿A qué hora es el desayuno?" (What time is breakfast?).',words:[['el taxi','taxi','Taxi','tak-see','ٹیکسی'],['A la estación, por favor','To the station, please','Station le chalein','ah lah es-tah-see-on','اسٹیشن لے چلیں'],['a la izquierda','to the left','Bayein taraf','ah lah ees-kee-er-da','بائیں طرف'],['a la derecha','to the right','Dayein taraf','ah lah deh-reh-cha','دائیں طرف'],['recto / todo recto','straight ahead','Seedha','rek-to','سیدھا'],['el hotel','hotel','Hotel','oh-tel — h silent','ہوٹل'],['Tengo una reserva','I have a booking','Meri booking hai','ten-go oo-na reh-ser-va','میری بکنگ ہے'],['la llave','the key','Chaabi','yah-veh','چابی'],['el aeropuerto','airport','Airport','ah-eh-ro-pwer-to','ایئرپورٹ'],['¿Dónde está...?','Where is...?','... kahan hai?','don-deh es-ta','...... کہاں ہے?'],['cerca / lejos','near / far','Qareeb / door','ser-ka / leh-hos','قریب  /  دور'],['la salida','exit','Nikalne ka rasta','sah-lee-da','نکلنے کا راستہ']],sents:[['¿Dónde está el hotel?','Where is the hotel?','Hotel kahan hai?'],['Está cerca, a la derecha.','It is near, on the right.','Qareeb hai, dayein taraf.'],['¿Cuánto cuesta el taxi al aeropuerto?','How much is the taxi to the airport?','Airport tak taxi kitne ka hai?']],dlg:[['A','Buenas tardes. Al aeropuerto, por favor.','Good afternoon. To the airport, please.'],['B','Muy bien. ¿Tiene maletas?','Very well. Do you have suitcases?'],['A','Sí, una maleta. ¿Cuánto cuesta?','Yes, one suitcase. How much does it cost?'],['B','Veinte, por favor.','Twenty, please.']],quiz:[['"Left" is...',['derecha','izquierda','recto','cerca'],1,'Izquierda = left (bayein).'],['"Tengo una reserva" means...',['I want a room','I have a booking','I need the key','I am lost'],1,'Reserva = booking/reservation.'],['"Far" is...',['cerca','lejos','aquí','allí'],1,'Lejos = far (door). Cerca = near.'],['"La llave" is...',['The door','The key','The room','The ticket'],1,'Llave = key (chaabi).'],['Airport in Spanish: ',['la estación','el hotel','el aeropuerto','el taxi'],2,'Aeropuerto = airport.']]}
];


/* ── LAYER 1 · CONTENT (continued) ── */
/* ============ LESSONS 11-20 ============ */
LESSONS.push(
{n:11,t:'Shopping & Money',sub:'Prices and polite bargaining',ex:'Shopping words: tienda (shop), mercado (market), precio (price). Always ask "¿Cuánto cuesta?" (How much?). To bargain politely, smile and say "Es un poco caro" (It is a little expensive) or "¿Puede ser más barato?" (Can it be cheaper?). Pay with "efectivo" (cash) or "tarjeta" (card). Finish with "Me lo llevo" (I\'ll take it).',words:[['la tienda','shop','Dukaan','tee-en-da','دکان'],['¿Cuánto cuesta?','How much does it cost?','Kitne ka hai?','kwan-to kwes-ta','کتنے کا ہے?'],['Es caro','It is expensive','Mehnga hai','es kah-ro','مہنگا ہے'],['Es barato','It is cheap','Sasta hai','es bah-rah-to','سستا ہے'],['¿Puede ser más barato?','Can it be cheaper?','Kya thora sasta ho sakta hai?','pweh-deh ser mas bah-rah-to','کیا تھوڑا سستا ہو سکتا ہے?'],['el dinero','money','Paisy','dee-neh-ro','پیسے'],['Pagar en efectivo','Pay in cash','Cash dena','pah-gar en eh-fek-tee-vo','کیش دینا'],['la tarjeta','card','Card','tar-heh-ta — j = kh','کارڈ'],['Me lo llevo','I will take it','Main yeh le raha hoon','meh lo yeh-vo','میں یہ لے رہا ہوں'],['¿Tiene otro color?','Do you have another colour?','Kya doosra rang hai?','tee-eh-neh oh-tro ko-lor','کیا دوسرا رنگ ہے?'],['Solo estoy mirando','I am just looking','Bas dekh raha hoon','so-lo es-toy mee-ran-do','بس دیکھ رہا ہوں'],['un descuento','a discount','Riyayat','oon des-kwen-to','رعایت']],sents:[['¿Cuánto cuesta esta camisa?','How much does this shirt cost?','Yeh qameez kitne ki hai?'],['Es un poco caro. ¿Tiene un descuento?','It is a little expensive. Is there a discount?','Thora mehnga hai. Koi discount hai?'],['Perfecto, me lo llevo.','Perfect, I\'ll take it.','Perfect, main yeh le raha hoon.']],dlg:[['A','Buenos días. ¿Cuánto cuesta?','Good morning. How much does it cost?'],['B','Cuesta cien.','It costs one hundred.'],['A','Es un poco caro. ¿Ochenta?','It is a bit expensive. Eighty?'],['B','Está bien, ochenta.','Okay, eighty.'],['A','Gracias, me lo llevo.','Thanks, I will take it.']],quiz:[['"Caro" means...',['Cheap','Expensive','Big','New'],1,'Caro = expensive (mehnga).'],['"Me lo llevo" means...',['I am just looking','I will take it','Too expensive','Do you have it?'],1,'Me lo llevo = I\'ll take it.'],['Cash in Spanish: ',['tarjeta','efectivo','precio','dinero total'],1,'Efectivo = cash.'],['"¿Cuánto cuesta?" asks...',['What size?','What colour?','How much does it cost?','Is it open?'],2,'The key shopping question!'],['"Solo estoy mirando" means...',['I want to pay','I am just looking','I need a bag','I will buy it'],1,'Use it when you only browse.']]},
{n:12,t:'Daily Routine Verbs',sub:'Wake up, eat, work, sleep',ex:'Talk about your day with reflexive verbs — they end in -se and use me/te/se: despertarse (to wake up) → "Me despierto a las seis" (I wake up at six). More: levantarse (get up), ducharse (shower), desayunar (eat breakfast), trabajar (work), volver (return), cenar (eat dinner), acostarse (go to bed), dormir (sleep). Order your day with primero (first), luego (then), después (after).',words:[['me despierto','I wake up','Main jaagta hoon','meh des-pee-er-to','میں جاگتا ہوں'],['me levanto','I get up','Main uthta hoon','meh leh-van-to','میں اٹھتا ہوں'],['desayuno','I have breakfast','Main nashta karta hoon','deh-sah-yoo-no','میں ناشتہ کرتا ہوں'],['trabajo','I work','Main kaam karta hoon','tra-bah-ho','میں کام کرتا ہوں'],['como','I eat (lunch)','Main khana khata hoon','ko-mo','میں کھانا کھاتا ہوں'],['vuelvo a casa','I return home','Main ghar wapas aata hoon','vwel-vo ah kah-sa','میں گھر واپس آٹا ہوں'],['ceno','I have dinner','Main raat ka khana khata hoon','seh-no','میں رات کا کھانا کھاتا ہوں'],['me acuesto','I go to bed','Main sonay jata hoon','meh ah-kwes-to','میں سونے جاتا ہوں'],['duermo','I sleep','Main sota hoon','dwer-mo','میں سوتا ہوں'],['todos los días','every day','Har roz','to-dos los dee-as','ہر روز'],['primero / luego','first / then','Pehle / phir','pree-meh-ro / lweh-go','پہلے  /  پھر'],['a las seis','at six o\'clock','Chhe bajay','ah las seys','چھ بجے']],sents:[['Me despierto a las seis de la mañana.','I wake up at 6 in the morning.','Main subah chhe bajay jaagta hoon.'],['Trabajo de nueve a cinco.','I work from nine to five.','Main nau se paanch kaam karta hoon.'],['Me acuesto a las once.','I go to bed at eleven.','Main gyarah bajay sota hoon.']],dlg:[['A','¿A qué hora te despiertas?','What time do you wake up?'],['B','Me despierto a las seis. Luego desayuno.','I wake up at six. Then I have breakfast.'],['A','¿Y a qué hora te acuestas?','And what time do you go to bed?'],['B','Me acuesto a las once de la noche.','I go to bed at 11 at night.']],quiz:[['"Me despierto" means...',['I sleep','I wake up','I eat','I work'],1,'Despertarse = to wake up.'],['"Every day" is...',['hoy','todos los días','a veces','mañana'],1,'Todos los días = every day (har roz).'],['"I sleep" (dormir) is...',['duermo','despierto','como','ceno'],0,'Dormir: yo duermo (stem changes!).'],['"Then / afterwards" is...',['primero','luego','nunca','siempre'],1,'Luego = then. Primero = first.'],['"Me acuesto a las diez" means...',['I wake at ten','I eat at ten','I go to bed at ten','I work at ten'],2,'Acostarse = to go to bed.']]},
{n:13,t:'Past Tense Basics',sub:'Yesterday I... — talking about the past',ex:'To talk about yesterday, Spanish uses the preterite. Regular -ar verbs: yo -é, tú -aste, él -ó. Hablar → "Ayer hablé con mi amigo" (Yesterday I spoke with my friend). -er/-ir verbs: yo -í, él -ió: comer → "Comí arroz" (I ate rice). Two super-common irregulars to memorise: fui (I went / I was) and hice (I did/made). Start past stories with "ayer" (yesterday).',words:[['ayer','yesterday','Kal (guzra)','ah-yer','کل (گزرا)'],['hablé','I spoke','Main ne baat ki','ah-bleh','میں نے بات کی'],['comí','I ate','Main ne khaya','ko-mee','میں نے کھایا'],['fui','I went / I was','Main gaya / tha','fwee','میں گیا  /  تھا'],['hice','I did / made','Main ne kiya','ee-seh','میں نے کیا'],['trabajé','I worked','Main ne kaam kiya','tra-bah-heh','میں نے کام کیا'],['compré','I bought','Main ne kharida','kom-preh','میں نے خریدا'],['vi','I saw','Main ne dekha','vee','میں نے دیکھا'],['la semana pasada','last week','Pichle haftay','seh-mah-na pah-sah-da','پچھلے ہفتے'],['anoche','last night','Kal raat','ah-no-cheh','کل رات'],['llegué','I arrived','Main pohancha','yeh-geh','میں پہنچا'],['estudié','I studied','Main ne parha','es-too-dee-eh','میں نے پڑھا']],sents:[['Ayer trabajé mucho.','Yesterday I worked a lot.','Kal main ne bohat kaam kiya.'],['Fui al mercado y compré pan.','I went to the market and bought bread.','Main bazaar gaya aur roti kharidi.'],['Anoche comí con mi familia.','Last night I ate with my family.','Kal raat main ne khandan ke saath khaya.']],dlg:[['A','¿Qué hiciste ayer?','What did you do yesterday?'],['B','Trabajé y luego fui al mercado.','I worked and then I went to the market.'],['A','¿Qué compraste?','What did you buy?'],['B','Compré fruta y pan.','I bought fruit and bread.']],quiz:[['"Ayer" means...',['Today','Tomorrow','Yesterday','Tonight'],2,'Ayer = yesterday.'],['"I ate" (comer, past) is...',['como','comí','comes','comió tú'],1,'Past yo for -er verbs = -í → comí.'],['"Fui al mercado" means...',['I am at the market','I went to the market','I go to the market','I want the market'],1,'Fui = I went (irregular past of ir).'],['"Hablé" is the past of...',['comer','hablar','vivir','hacer'],1,'Hablar → hablé (I spoke).'],['Last night is...',['ayer','anoche','mañana','la semana'],1,'Anoche = last night.']]},
{n:14,t:'Future with "Voy a..."',sub:'I am going to... — easy future',ex:'Good news: the easiest future needs no new endings! Use IR (to go) + a + verb: "Voy a estudiar" (I am going to study). Voy (I), vas (you), va (he/she), vamos (we), van (they). Add time words: mañana (tomorrow), esta noche (tonight), la semana que viene (next week). You already know "voy" from Lesson travel — now it builds your future!',words:[['voy a...','I am going to...','Main ... karne ja raha hoon','voy ah','میں ...... کرنے جا رہا ہوں'],['Voy a viajar','I am going to travel','Main safar karunga','voy ah vee-ah-har','میں سفر کروں گا'],['mañana','tomorrow','Kal','man-yah-na','کل'],['esta noche','tonight','Aaj raat','es-ta no-cheh','آج رات'],['la semana que viene','next week','Agle haftay','seh-mah-na keh vee-eh-neh','اگلے ہفتے'],['¿Vas a venir?','Are you going to come?','Kya tum aaoge?','vas ah veh-neer','کیا تم آؤ گے?'],['Vamos a comer','We are going to eat','Hum khayenge','vah-mos ah ko-mer','ہم کھائیں گے'],['Voy a aprender español','I am going to learn Spanish','Main Spanish seekhunga','voy ah ah-pren-der es-pan-yol','میں ہسپانوی سیکھوں گا'],['después','afterwards / later','Baad mein','des-pwes','بعد میں'],['pronto','soon','Jald','pron-to','جلد'],['Voy a llamar','I am going to call','Main call karunga','voy ah yah-mar','میں کال کروں گا'],['este fin de semana','this weekend','Is weekend','es-teh feen deh seh-mah-na','اس ویک اینڈ']],sents:[['Mañana voy a estudiar.','Tomorrow I am going to study.','Kal main parhunga.'],['Esta noche vamos a cenar juntos.','Tonight we are going to have dinner together.','Aaj raat hum saath khana khayenge.'],['Voy a viajar a España.','I am going to travel to Spain.','Main Spain ka safar karunga.']],dlg:[['A','¿Qué vas a hacer mañana?','What are you going to do tomorrow?'],['B','Voy a visitar a mi familia. ¿Y tú?','I am going to visit my family. And you?'],['A','Voy a estudiar español.','I am going to study Spanish.'],['B','¡Buena idea!','Good idea!']],quiz:[['"Voy a comer" means...',['I ate','I am going to eat','I eat now','I want food'],1,'Voy a + verb = going to...'],['"Tomorrow" is...',['ayer','mañana','hoy','anoche'],1,'Mañana = tomorrow.'],['"We are going to..." is...',['voy a','vas a','vamos a','van a'],2,'We = vamos a.'],['Tonight is...',['esta mañana','esta noche','esta semana','este día'],1,'Noche = night → esta noche.'],['To build this future you need verb...',['ser','ir (voy, vas, va...)','tener','hacer'],1,'IR + a + infinitive.']]},
{n:15,t:'Health & Emergency Phrases',sub:'Phrases that can really help you',ex:'Health phrases are important. Learn them before you need them! "Me duele..." + body part = "... hurts": "Me duele la cabeza" (My head hurts). "Tengo fiebre" (I have a fever), "Estoy enfermo/a" (I am sick — enfermo for men, enferma for women). Emergency: "¡Ayuda!" (Help!), "Es una emergencia", "Llama a una ambulancia" (Call an ambulance). Pharmacy = farmacia — look for the green cross in Spain.',words:[['¡Ayuda!','Help!','Madad!','ah-yoo-da','مدد!'],['Estoy enfermo','I am sick','Main beemar hoon','es-toy en-fer-mo','میں بیمار ہوں'],['Me duele la cabeza','My head hurts','Mere sar mein dard hai','meh dweh-leh lah kah-beh-sa','میرے سر میں درد ہے'],['Tengo fiebre','I have a fever','Mujhe bukhar hai','ten-go fee-eh-breh','مجھے بخار ہے'],['el médico','doctor','Doctor','meh-dee-ko','ڈاکٹر'],['el hospital','hospital','Hospital','os-pee-tal — h silent','ہسپتال'],['la farmacia','pharmacy','Dawai ki dukaan','far-mah-see-ah','دوائی کی دکان'],['la medicina','medicine','Dawai','meh-dee-see-na','دوائی'],['Necesito un médico','I need a doctor','Mujhe doctor chahiye','neh-seh-see-to oon meh-dee-ko','مجھے ڈاکٹر چاہیے'],['Es una emergencia','It is an emergency','Yeh emergency hai','es oo-na eh-mer-hen-see-ah','یہ ایمرجنسی ہے'],['Llama a una ambulancia','Call an ambulance','Ambulance bulao','yah-ma ah oo-na am-boo-lan-see-ah','ایمبولینس بلاؤ'],['Tengo tos','I have a cough','Mujhe khansi hai','ten-go tos','مجھے کھانسی ہے']],sents:[['Me duele el estómago.','My stomach hurts.','Mere pait mein dard hai.'],['¿Dónde hay una farmacia?','Where is there a pharmacy?','Dawai ki dukaan kahan hai?'],['Necesito descansar.','I need to rest.','Mujhe aaram karna hai.']],dlg:[['A','¿Qué te pasa?','What is wrong with you?'],['B','Estoy enfermo. Me duele la cabeza y tengo fiebre.','I am sick. My head hurts and I have a fever.'],['A','¿Necesitas un médico?','Do you need a doctor?'],['B','Sí, por favor. ¿Dónde está el hospital?','Yes, please. Where is the hospital?']],quiz:[['"Me duele la cabeza" means...',['I have a fever','My head hurts','I am hungry','I need water'],1,'Duele = hurts, cabeza = head.'],['Fever is...',['tos','fiebre','dolor','frío'],1,'Fiebre = fever (bukhar).'],['"¡Ayuda!" means...',['Water!','Help!','Stop!','Doctor!'],1,'Ayuda = help (madad).'],['Pharmacy is...',['hospital','farmacia','medicina','ambulancia'],1,'Farmacia = pharmacy.'],['"Estoy enfermo" means...',['I am tired','I am sick','I am late','I am ready'],1,'Enfermo = sick (beemar).']]},
{n:16,t:'Phone & Internet Words',sub:'Mobile, Wi-Fi and messages',ex:'Modern life words: móvil (mobile phone), contraseña (password), wifi (pronounced "wee-fee" in Spanish!), mensaje (message), llamada (call). Ask for Wi-Fi politely: "¿Cuál es la contraseña del wifi?" (What is the Wi-Fi password?). "No tengo señal" = I have no signal. "Se acabó la batería" = The battery died.',words:[['el móvil','mobile phone','Mobile','moh-veel','موبائل'],['la contraseña del wifi','the Wi-Fi password','Wi-Fi ka password','kon-tra-sen-ya del wee-fee','وائی فائی کا پاس ورڈ'],['un mensaje','a message','Message','men-sah-heh','پیغام'],['una llamada','a phone call','Call','yah-mah-da','کال'],['Voy a llamarte','I am going to call you','Main tumhe call karunga','voy ah yah-mar-teh','میں تمہیں کال کروں گا'],['No tengo señal','I have no signal','Signal nahi hai','no ten-go sen-yal','سگنل نہیں ہے'],['la batería','battery','Battery','bah-teh-ree-ah','بیٹری'],['cargar el móvil','to charge the phone','Mobile charge karna','kar-gar el moh-veel','موبائل چارج کرنا'],['internet','internet','Internet','een-ter-net','انٹرنیٹ'],['el correo electrónico','email','Email','ko-rreh-oh eh-lek-tro-nee-ko','ای میل'],['una foto','a photo','Tasveer','fo-to','تصویر'],['¿Cuál es tu número?','What is your number?','Aap ka number kya hai?','kwal es too noo-meh-ro','آپ کا نمبر کیا ہے?']],sents:[['¿Cuál es la contraseña del wifi?','What is the Wi-Fi password?','Wi-Fi ka password kya hai?'],['Te envío un mensaje.','I will send you a message.','Main tumhe message bhejta hoon.'],['Mi móvil no tiene batería.','My phone has no battery.','Mere mobile ki battery khatam hai.']],dlg:[['A','Perdón, ¿hay wifi aquí?','Excuse me, is there Wi-Fi here?'],['B','Sí. La contraseña es "hotel2024".','Yes. The password is "hotel2024".'],['A','Gracias. ¿Puedo cargar mi móvil?','Thanks. Can I charge my phone?'],['B','Claro, allí.','Of course, over there.']],quiz:[['"Contraseña" means...',['Message','Password','Number','Battery'],1,'Contraseña = password.'],['"Una llamada" is...',['A photo','A call','An email','A phone'],1,'Llamada = call.'],['"No tengo señal" means...',['No battery','No signal','No Wi-Fi','No money'],1,'Señal = signal.'],['Email in Spanish: ',['mensaje','correo electrónico','internet','foto'],1,'Correo electrónico = email.'],['"Voy a llamarte" means...',['Call me','I am going to call you','You called me','I have your number'],1,'Llamar + te = call you.']]},
{n:17,t:'Jobs & Work Talk',sub:'What do you do for work?',ex:'Ask about work: "¿A qué te dedicas?" or "¿En qué trabajas?" Answer with "Soy..." + job: Soy maestro (teacher), Soy conductor (driver), Soy cocinero (cook). Or "Trabajo en..." + place: "Trabajo en una oficina" (I work in an office). Looking for work? "Busco trabajo" = I am looking for work. "La entrevista" = the interview.',words:[['¿A qué te dedicas?','What do you do for work?','Aap kya kaam karte hain?','ah keh teh deh-dee-kas','آپ کیا کام کرتے ہیں?'],['Soy maestro','I am a teacher','Main ustad hoon','soy mah-es-tro','میں استاد ہوں'],['el trabajo','work / job','Kaam / naukri','tra-bah-ho','کام  /  نوکری'],['Busco trabajo','I am looking for work','Main naukri dhoond raha hoon','boos-ko tra-bah-ho','میں نوکری ڈھونڈ رہا ہوں'],['la oficina','office','Daftar','oh-fee-see-na','دفتر'],['el jefe','boss','Boss','heh-feh — j = kh','باس'],['la entrevista','interview','Interview','en-treh-vees-ta','انٹرویو'],['Trabajo en un hospital','I work in a hospital','Main hospital mein kaam karta hoon','tra-bah-ho en oon os-pee-tal','میں ہسپتال میں کام کرتا ہوں'],['el horario','schedule / hours','Time table','oh-rah-ree-oh','ٹائم ٹیبل'],['ganar dinero','to earn money','Paisy kamana','gah-nar dee-neh-ro','پیسے کمانا'],['el compañero de trabajo','work colleague','Kaam ka saathi','kom-pan-yeh-ro deh tra-bah-ho','کام کا ساتھی'],['Estoy ocupado','I am busy','Main masroof hoon','es-toy oh-koo-pah-do','میں مصروف ہوں']],sents:[['Trabajo de lunes a viernes.','I work from Monday to Friday.','Main Peer se Jumma kaam karta hoon.'],['Busco trabajo en una oficina.','I am looking for work in an office.','Main daftar mein naukri dhoond raha hoon.'],['Mi jefe es muy amable.','My boss is very kind.','Mera boss bohat naram dil hai.']],dlg:[['A','¿A qué te dedicas?','What do you do for work?'],['B','Soy cocinero. Trabajo en un restaurante.','I am a cook. I work in a restaurant.'],['A','¡Qué interesante! Yo soy maestro.','How interesting! I am a teacher.'],['B','¿Te gusta tu trabajo?','Do you like your job?'],['A','Sí, me gusta mucho.','Yes, I like it a lot.']],quiz:[['"Busco trabajo" means...',['I have work','I am looking for work','I lost work','I love work'],1,'Busco = I look for (dhoondna).'],['Teacher is...',['cocinero','maestro','jefe','conductor'],1,'Maestro = teacher (ustad).'],['"¿A qué te dedicas?" asks...',['Where do you live?','What do you do for work?','Are you busy?','When do you work?'],1,'The classic job question.'],['Office is...',['oficina','entrevista','horario','empresa'],0,'Oficina = office (daftar).'],['"Estoy ocupado" means...',['I am tired','I am busy','I am free','I am late'],1,'Ocupado = busy (masroof).']]},
{n:18,t:'Feelings & Opinions',sub:'Me gusta, creo que... — saying what you think',ex:'Feelings: estoy contento (happy), triste (sad), cansado (tired), nervioso (nervous). Likes use GUSTAR backwards: "Me gusta el té" = Tea pleases me → I like tea. Plural: "Me gustan las frutas" (I like fruits). Opinions: "Creo que..." (I think that...), "En mi opinión..." (In my opinion...), "Estoy de acuerdo" (I agree).',words:[['Me gusta','I like (one thing)','Mujhe pasand hai','meh goos-ta','مجھے پسند ہے'],['Me gustan','I like (many things)','Mujhe (cheezein) pasand hain','meh goos-tan','مجھے (چیزیں) پسند ہیں'],['No me gusta','I do not like','Mujhe pasand nahi','no meh goos-ta','مجھے پسند نہیں'],['Estoy contento','I am happy','Main khush hoon','es-toy kon-ten-to','میں خوش ہوں'],['Estoy triste','I am sad','Main udaas hoon','es-toy trees-teh','میں اداس ہوں'],['Estoy nervioso','I am nervous','Main ghabraya hua hoon','es-toy ner-vee-oh-so','میں گھبرایا ہوا ہوں'],['Creo que sí','I think so (yes)','Mera khayal hai haan','kreh-oh keh see','میرا خیال ہے ہاں'],['En mi opinión','In my opinion','Meri raaye mein','en mee oh-pee-nee-on','میری رائے میں'],['Estoy de acuerdo','I agree','Main mutafiq hoon','es-toy deh ah-kwer-do','میں متفق ہوں'],['Me encanta','I love it','Mujhe bohat pasand hai','meh en-kan-ta','مجھے بہت پسند ہے'],['Tengo miedo','I am afraid','Mujhe dar lagta hai','ten-go mee-eh-do','مجھے ڈر لگتا ہے'],['¡Qué bien!','How great!','Kitni achi baat hai!','keh bee-en','کتنی اچھی بات ہے!']],sents:[['Me gusta mucho el fútbol.','I like football a lot.','Mujhe football bohat pasand hai.'],['Me gustan las manzanas.','I like apples.','Mujhe saib pasand hain.'],['Creo que es una buena idea.','I think it is a good idea.','Mera khayal hai yeh acha khayal hai.']],dlg:[['A','¿Te gusta el té?','Do you like tea?'],['B','Sí, me encanta. ¿Y a ti?','Yes, I love it. And you?'],['A','A mí también. Pero no me gusta el café.','Me too. But I do not like coffee.'],['B','Estoy de acuerdo, el té es mejor.','I agree, tea is better.']],quiz:[['"I like apples" (plural) is...',['Me gusta las manzanas','Me gustan las manzanas','Me gusto manzanas','Gusta manzanas yo'],1,'Plural things → gustan.'],['"Creo que..." means...',['I want that...','I think that...','I know that...','I see that...'],1,'Creo = I think/believe.'],['"I agree" is...',['Estoy cansado','Estoy de acuerdo','Me gusta','Creo que no'],1,'Estoy de acuerdo = I agree.'],['"Estoy triste" means...',['I am happy','I am sad','I am angry','I am surprised'],1,'Triste = sad (udaas).'],['"Me encanta" is stronger than "me gusta" and means...',['I hate it','I love it','I need it','I see it'],1,'Encanta = love it (bohat pasand).']]},
{n:19,t:'Making Plans & Invitations',sub:'¿Quieres...? — inviting friends',ex:'Invite with "¿Quieres...?" (Do you want...?) + verb: "¿Quieres tomar un té?" (Do you want to have a tea?). Suggest with "¿Por qué no...?" (Why don\'t we...?). Fix a time: "¿A qué hora?" and a place: "En el parque". Accept happily: "¡Claro!" (Of course!), "¡Buena idea!" (Good idea!). Say no politely: "Lo siento, no puedo" (Sorry, I can\'t).',words:[['¿Quieres un té?','Do you want a tea?','Kya tum chai peeyoge?','kee-eh-res oon teh','کیا تم چائے پیو گے?'],['¿Por qué no vamos...?','Why don\'t we go...?','Hum ... kyun na chalein?','por keh no vah-mos','ہم ...... کیوں نہ چلیں?'],['¡Claro!','Of course!','Bilkul!','klah-ro','بالکل!'],['¡Buena idea!','Good idea!','Acha khayal hai!','bweh-na ee-deh-ah','اچھا خیال ہے!'],['Lo siento, no puedo','Sorry, I can\'t','Maafi, main nahi aa sakta','lo see-en-to no pweh-do','معافی, میں نہیں آ سکتا'],['¿A qué hora?','At what time?','Kis waqt?','ah keh oh-ra','کس وقت?'],['esta tarde','this afternoon/evening','Aaj shaam','es-ta tar-deh','آج شام'],['el fin de semana','the weekend','Weekend','feen deh seh-mah-na','ویک اینڈ'],['quedar','to arrange to meet','Milna tay karna','keh-dar','ملنا طے کرنا'],['Te invito','I invite you (my treat)','Meri taraf se dawat','teh een-vee-to','میری طرف سے دعوت'],['conmigo','with me','Mere saath','kon-mee-go','میرے ساتھ'],['¡Vamos!','Let\'s go!','Chalo!','vah-mos','چلو!']],sents:[['¿Quieres tomar un té conmigo?','Do you want to have a tea with me?','Kya tum mere saath chai peeyoge?'],['Quedamos a las cinco en el parque.','We will meet at five in the park.','Hum paanch bajay park mein milenge.'],['¿Por qué no vamos al cine?','Why don\'t we go to the cinema?','Hum cinema kyun na chalein?']],dlg:[['A','¿Quieres tomar un café esta tarde?','Do you want a coffee this afternoon?'],['B','¡Buena idea! ¿A qué hora?','Good idea! At what time?'],['A','A las cinco, en la plaza.','At five, in the square.'],['B','Perfecto. ¡Hasta las cinco!','Perfect. See you at five!']],quiz:[['"¿Quieres...?" means...',['Where is...?','Do you want...?','Can you...?','When is...?'],1,'Quieres = do you want.'],['"Lo siento, no puedo" means...',['Sorry, I can\'t','Sorry, I am late','Sorry, I forgot','Yes, of course'],0,'No puedo = I cannot.'],['"¡Buena idea!" means...',['Good morning!','Good idea!','Good luck!','Goodbye!'],1,'Idea = idea (khayal).'],['"Conmigo" means...',['With you','With me','With him','Alone'],1,'Conmigo = with me (mere saath).'],['"Esta tarde" is...',['Tonight','This afternoon','Tomorrow','Yesterday'],1,'Tarde = afternoon/evening.']]},
{n:20,t:'Full Conversation Review',sub:'Everything together — you can do this!',ex:'Congratulations — this is your review lesson! A full conversation uses everything: greetings, ser/estar, questions, food, plans and goodbyes. Read the dialogue slowly, listen to every line, then answer like you are Person B. If this feels hard, repeat lessons 6, 7 and 19 — then come back. After this quiz, continue with Flashcards and the Verb Trainer daily. ¡Poco a poco! (Little by little!)',words:[['todo','everything / all','Sab kuch','to-do','سب کچھ'],['también','also / too','Bhi','tam-bee-en','بھی'],['porque','because','Kyunke','por-keh','کیونکہ'],['pero','but','Lekin','peh-ro','لیکن'],['y','and','Aur','ee','اور'],['muy','very','Bohat','mwee','بہت'],['un poco','a little','Thora sa','oon po-ko','تھوڑا سا'],['ahora','now','Abhi','ah-oh-ra','ابھی'],['hablar','to speak','Bolna','ah-blar','بولنا'],['aprender','to learn','Seekhna','ah-pren-der','سیکھنا'],['la práctica','practice','Mashq / practice','prak-tee-ka','مشق  /  مشق'],['¡Enhorabuena!','Congratulations!','Mubarak ho!','en-oh-ra-bweh-na','مبارک ہو!']],sents:[['Hola, soy Farrakh, soy de Pakistán y hablo urdu, inglés y un poco de español.','Hello, I am Farrakh, I am from Pakistan and I speak Urdu, English and a little Spanish.','Assalam-o-Alaikum, main Farrakh hoon, main Pakistan se hoon aur main Urdu, English aur thori Spanish bolta hoon.'],['Estudio español todos los días porque me gusta mucho.','I study Spanish every day because I like it a lot.','Main har roz Spanish parhta hoon kyunke mujhe bohat pasand hai.'],['Mañana voy a practicar con un amigo.','Tomorrow I am going to practise with a friend.','Kal main ek dost ke saath practice karunga.']],dlg:[['A','¡Hola! ¿Cómo te llamas?','Hello! What is your name?'],['B','Me llamo Farrakh. Soy de Pakistán.','My name is Farrakh. I am from Pakistan.'],['A','¿Qué idiomas hablas?','What languages do you speak?'],['B','Hablo urdu e inglés, y ahora aprendo español.','I speak Urdu and English, and now I am learning Spanish.'],['A','¿Te gusta el español?','Do you like Spanish?'],['B','¡Me encanta! Estudio todos los días.','I love it! I study every day.'],['A','¿Quieres practicar mañana?','Do you want to practise tomorrow?'],['B','¡Claro! Quedamos a las diez.','Of course! We will meet at ten.']],quiz:[['"También" means...',['But','Also','Because','Now'],1,'También = also (bhi).'],['"Hablo urdu e inglés" — why "e" not "y"?',['It is a mistake','"y" becomes "e" before i-sounds','It means "or"','It is formal'],1,'Grammar gem: y → e before words starting with i/hi.'],['"Ahora aprendo español" means...',['Yesterday I learned','Now I am learning Spanish','I will learn later','I never learn'],1,'Ahora = now, aprendo = I learn.'],['"Quedamos a las diez" means...',['We eat at ten','We meet at ten','We sleep at ten','We work at ten'],1,'Quedar = to arrange/meet (tay milna).'],['Which sentence is fully correct?',['Yo soy cansado hoy','Estoy de Pakistán','Soy de Pakistán y estoy contento','Es en casa'],2,'Origin = soy (ser), feeling = estoy (estar). Perfect!']]}
);


/* ── LAYER 1 · CONTENT (continued) ── */
/* ============ LESSONS 21-30 (A2 PACK) ============ */
LESSONS.push(
{n:21,t:'Weather Talk',sub:'Small talk about the weather — very Spanish!',ex:'Weather is the safest small talk in Spain. Most weather sentences use HACER: hace sol (it is sunny), hace calor (hot), hace frío (cold), hace viento (windy). For rain and snow Spanish uses verbs: llueve (it rains), nieva (it snows). Ask with "¿Qué tiempo hace?" Tomorrow\'s weather: "Mañana hará sol" — but simpler with your future: "Mañana va a llover" (tomorrow it is going to rain).',words:[['¿Qué tiempo hace?','What is the weather like?','Mausam kaisa hai?','keh tee-em-po ah-seh','موسم کیسا ہے?'],['hace sol','it is sunny','Dhoop hai','ah-seh sol','دھوپ ہے'],['hace calor','it is hot','Garmi hai','ah-seh kah-lor','گرمی ہے'],['hace frío','it is cold','Sardi hai','ah-seh free-oh','سردی ہے'],['hace viento','it is windy','Hawa chal rahi hai','ah-seh vee-en-to','ہوا چل رہی ہے'],['está nublado','it is cloudy','Badal chaye hain','es-ta noo-blah-do','بادل چائے ہیں'],['llueve','it is raining','Barish ho rahi hai','yweh-veh — ll = y','بارش ہو رہی ہے'],['nieva','it is snowing','Barf par rahi hai','nee-eh-va','برف پر رہی ہے'],['la tormenta','storm','Toofan','tor-men-ta','طوفان'],['el paraguas','umbrella','Chhatri','pah-rah-gwas','چھتری'],['¿Va a llover?','Is it going to rain?','Kya barish hogi?','va ah yo-ver','کیا بارش ہوگی?'],['¡Qué buen tiempo!','What lovely weather!','Kitna acha mausam hai!','keh bwen tee-em-po','کتنا اچھا موسم ہے!']],sents:[['Hoy hace mucho calor.','Today it is very hot.','Aaj bohat garmi hai.'],['Mañana va a llover, lleva un paraguas.','Tomorrow it is going to rain, take an umbrella.','Kal barish hogi, chhatri le jana.'],['En invierno hace frío y a veces nieva.','In winter it is cold and sometimes it snows.','Sardiyon mein sardi hoti hai aur kabhi barf parti hai.']],dlg:[['A','¡Hola! ¿Qué tiempo hace hoy?','Hello! What is the weather like today?'],['B','Hace sol y calor. ¡Un día perfecto!','It is sunny and hot. A perfect day!'],['A','¿Y mañana?','And tomorrow?'],['B','Mañana va a llover por la tarde.','Tomorrow it is going to rain in the afternoon.']],quiz:[['"Hace frío" means...',['It is sunny','It is cold','It is raining','It is windy'],1,'Frío = cold (sardi).'],['Rain as a verb — "it is raining" is...',['hace lluvia','llueve','está agua','nieva'],1,'Llueve = it rains. Nieva = it snows.'],['"¿Qué tiempo hace?" asks...',['What time is it?','What is the weather like?','What day is it?','How are you?'],1,'Tiempo here = weather (mausam).'],['Umbrella in Spanish: ',['el paraguas','la tormenta','el viento','la nube'],0,'Paraguas = umbrella (chhatri).'],['"Mañana va a llover" means...',['It rained yesterday','Tomorrow it is going to rain','It never rains','I like rain'],1,'Va a + llover = going to rain.']]},
{n:22,t:'At the Doctor (deep)',sub:'Explaining exactly what hurts',ex:'Go deeper than Lesson 15. Describe symptoms with TENER: tengo dolor de... (I have a pain in...), tengo náuseas (I feel sick), estoy mareado (I am dizzy). Say when it started: "desde ayer" (since yesterday), "desde hace dos días" (for two days). The doctor may say: "Abra la boca" (Open your mouth), "Respire" (Breathe), "Tiene que descansar" (You must rest), "Tome esto dos veces al día" (Take this twice a day).',words:[['tengo dolor de espalda','I have back pain','Meri kamar mein dard hai','ten-go do-lor deh es-pal-da','میری کمر میں درد ہے'],['estoy mareado','I am dizzy','Mujhe chakkar aa rahe hain','es-toy mah-reh-ah-do','مجھے چکر آ رہے ہیں'],['tengo náuseas','I feel sick / nauseous','Mera dil matla raha hai','ten-go now-seh-as','میرا دل متلا رہا ہے'],['desde ayer','since yesterday','Kal se','des-deh ah-yer','کل سے'],['desde hace dos días','for two days','Do din se','des-deh ah-seh dos dee-as','دو دن سے'],['la receta','prescription','Dawai ka nuskha','reh-seh-ta','دوائی کا نسخہ'],['dos veces al día','twice a day','Din mein do dafa','dos veh-ses al dee-a','دن میں دو دفعہ'],['¿Es grave?','Is it serious?','Kya yeh khatarnak hai?','es grah-veh','کیا یہ خطرناک ہے?'],['Necesito un análisis','I need a test','Mujhe test karwana hai','neh-seh-see-to oon ah-nah-lee-sees','مجھے ٹیسٹ کروانا ہے'],['Soy alérgico a...','I am allergic to...','Mujhe ... se allergy hai','soy ah-ler-hee-ko ah','مجھے ...... سے الرجی ہے'],['Respire profundo','Breathe deeply','Gehri saans lein','res-pee-reh pro-foon-do','گہری سانس لیں'],['Tiene que descansar','You must rest','Aap ko aaram karna chahiye','tee-eh-neh keh des-kan-sar','آپ کو آرام کرنا چاہیے']],sents:[['Tengo dolor de garganta desde hace tres días.','I have had a sore throat for three days.','Mujhe teen din se galay mein dard hai.'],['¿Es grave, doctor?','Is it serious, doctor?','Kya yeh khatarnak hai, doctor sahab?'],['Tome una pastilla dos veces al día.','Take one pill twice a day.','Ek goli din mein do dafa lein.']],dlg:[['A','Buenos días. ¿Qué le duele?','Good morning. What hurts?'],['B','Me duele la espalda y estoy mareado.','My back hurts and I am dizzy.'],['A','¿Desde cuándo?','Since when?'],['B','Desde ayer. ¿Es grave?','Since yesterday. Is it serious?'],['A','No es grave. Tiene que descansar y beber agua.','It is not serious. You must rest and drink water.']],quiz:[['"Estoy mareado" means...',['I am hungry','I am dizzy','I am angry','I am late'],1,'Mareado = dizzy (chakkar).'],['"Since yesterday" is...',['desde ayer','hasta ayer','para ayer','con ayer'],0,'Desde = since/from.'],['Prescription in Spanish: ',['la pastilla','la receta','la cita','la tos'],1,'Receta = prescription (nuskha).'],['"Dos veces al día" means...',['Two days','Twice a day','Every day','One day'],1,'Veces = times, al día = a day.'],['"¿Es grave?" asks...',['Is it free?','Is it serious?','Is it ready?','Is it far?'],1,'Grave = serious (khatarnak).']]},
{n:23,t:'Renting a House',sub:'Finding and renting a home',ex:'Renting words: el alquiler (the rent), el piso (flat/apartment), la habitación (room), amueblado (furnished). Ask: "¿Cuánto es el alquiler al mes?" (How much is the monthly rent?), "¿Está amueblado?" (Is it furnished?), "¿Incluye los gastos?" (Does it include bills?). Signing: el contrato (contract), la fianza (deposit — usually 1–2 months in Spain), "¿Cuándo puedo entrar?" (When can I move in?).',words:[['el alquiler','rent / renting','Kiraya','al-kee-ler','کرایہ'],['Busco un piso','I am looking for a flat','Main flat dhoond raha hoon','boos-ko oon pee-so','میں فلیٹ ڈھونڈ رہا ہوں'],['¿Cuánto es al mes?','How much is it per month?','Mahina kitna hai?','kwan-to es al mes','مہینہ کتنا ہے?'],['amueblado','furnished','Furniture ke saath','ah-mweh-blah-do','فرنیچر کے ساتھ'],['¿Incluye los gastos?','Does it include the bills?','Kya bill shamil hain?','een-kloo-yeh los gas-tos','کیا بل شامل ہیں?'],['el contrato','contract','Muahida','kon-trah-to','معاہدہ'],['la fianza','deposit','Zamanat / deposit','fee-an-sa','ضمانت  /  ڈپازٹ'],['la cocina equipada','fitted kitchen','Poora kitchen','ko-see-na eh-kee-pah-da','پورا کچن'],['¿Cuándo puedo entrar?','When can I move in?','Main kab andar aa sakta hoon?','kwan-do pweh-do en-trar','میں کب اندر آ سکتا ہوں?'],['el barrio','neighbourhood','Mohalla / ilaqa','bah-ree-oh','محلہ  /  علاقہ'],['tranquilo','quiet / calm','Pur-sukoon','tran-kee-lo','پرسکون'],['Tiene buena luz','It has good light','Is mein roshni achi hai','tee-eh-neh bweh-na loos','اس میں روشنی اچھی ہے']],sents:[['Busco un piso tranquilo cerca del centro.','I am looking for a quiet flat near the centre.','Main markaz ke qareeb pur-sukoon flat dhoond raha hoon.'],['El alquiler es seiscientos al mes, gastos incluidos.','The rent is 600 a month, bills included.','Kiraya 600 mahina hai, bill shamil.'],['¿Puedo ver el piso mañana?','Can I see the flat tomorrow?','Kya main kal flat dekh sakta hoon?']],dlg:[['A','Buenos días. Busco un piso. ¿Tiene algo?','Good morning. I am looking for a flat. Do you have anything?'],['B','Sí, un piso de dos habitaciones. El alquiler es quinientos al mes.','Yes, a two-room flat. The rent is 500 a month.'],['A','¿Está amueblado? ¿Y la fianza?','Is it furnished? And the deposit?'],['B','Sí, está amueblado. La fianza es un mes.','Yes, it is furnished. The deposit is one month.'],['A','Perfecto. ¿Cuándo puedo verlo?','Perfect. When can I see it?']],quiz:[['"El alquiler" means...',['The key','The rent','The contract','The room'],1,'Alquiler = rent (kiraya).'],['Deposit in Spanish: ',['la fianza','el gasto','el barrio','la luz'],0,'Fianza = deposit (zamanat).'],['"Amueblado" means...',['Big','Furnished','Quiet','Cheap'],1,'Amueblado = with furniture.'],['"¿Incluye los gastos?" asks...',['Is it near?','Does it include bills?','Is it quiet?','Can I enter?'],1,'Gastos = expenses/bills.'],['Neighbourhood is...',['el barrio','el piso','el mes','el alquiler total'],0,'Barrio = neighbourhood (mohalla).']]},
{n:24,t:'Bank & Money',sub:'Accounts, cards and changing money',ex:'Bank words: la cuenta (account), abrir una cuenta (open an account), el cajero automático (cash machine/ATM), sacar dinero (take out money), ingresar (pay in), la transferencia (bank transfer). Ask: "¿Dónde hay un cajero?" (Where is an ATM?), "Quiero cambiar dinero" (I want to change money). Watch out: "¿Cuál es la comisión?" (What is the fee?) — small word, big money!',words:[['el banco','bank','Bank','ban-ko','بینک'],['abrir una cuenta','to open an account','Account kholna','ah-breer oo-na kwen-ta','اکاؤنٹ کھولنا'],['el cajero automático','ATM / cash machine','ATM','kah-heh-ro ow-to-mah-tee-ko','اے ٹی ایم'],['sacar dinero','to withdraw money','Paisy nikalna','sah-kar dee-neh-ro','پیسے نکلنا'],['ingresar dinero','to pay in money','Paisy jama karna','een-greh-sar','پیسے جمع کرنا'],['la transferencia','bank transfer','Transfer','trans-feh-ren-see-a','ٹرانسفر'],['¿Dónde hay un cajero?','Where is an ATM?','ATM kahan hai?','don-deh ay oon kah-heh-ro','اے ٹی ایم کہاں ہے?'],['Quiero cambiar dinero','I want to change money','Main paisy tabdeel karna chahta hoon','kee-eh-ro kam-bee-ar dee-neh-ro','میں پیسے تبدیل کرنا چاہتا ہوں'],['la comisión','fee / commission','Fees / commission','ko-mee-see-on','فیس  /  کمیشن'],['el tipo de cambio','exchange rate','Rate','tee-po deh kam-bee-oh','ریٹ'],['Firmar aquí, por favor','Sign here, please','Yahan dastakhat karein','feer-mar ah-kee','یہاں دستخط کریں'],['el recibo','receipt','Raseed','reh-see-bo','رسید']],sents:[['Quiero abrir una cuenta, por favor.','I want to open an account, please.','Main ek account kholna chahta hoon.'],['¿Puedo sacar dinero con esta tarjeta?','Can I withdraw money with this card?','Kya main is card se paisy nikaal sakta hoon?'],['¿Cuál es la comisión por la transferencia?','What is the fee for the transfer?','Transfer ki fees kitni hai?']],dlg:[['A','Buenos días. Quiero abrir una cuenta.','Good morning. I want to open an account.'],['B','Claro. ¿Tiene su pasaporte?','Of course. Do you have your passport?'],['A','Sí, aquí está. ¿Tiene comisión la cuenta?','Yes, here it is. Does the account have a fee?'],['B','No, es gratis. Firme aquí, por favor.','No, it is free. Sign here, please.']],quiz:[['ATM in Spanish: ',['el cajero automático','la cuenta','la firma','el banco grande'],0,'Cajero automático = ATM.'],['"Sacar dinero" means...',['To save money','To withdraw money','To change money','To send money'],1,'Sacar = to take out.'],['"Quiero cambiar dinero" means...',['I want to open an account','I want to change money','I lost my money','I need a receipt'],1,'Cambiar = to change/exchange.'],['Receipt is...',['el recibo','la comisión','el tipo','la tarjeta nueva'],0,'Recibo = receipt (raseed).'],['Exchange rate is...',['el tipo de cambio','la cuenta','el cajero','la fianza'],0,'Tipo de cambio = exchange rate.']]},
{n:25,t:'Phone Call Practice',sub:'Saying it right on the phone',ex:'Phone Spanish has its own phrases. Answer with "¿Diga?" (Hello? — in Spain) or "¿Aló?" in Latin America. Ask for someone: "¿Está Sara?" (Is Sara there?). Useful lines: "Soy Farrakh" (It is Farrakh), "Un momento, ahora se pone" (One moment, she is coming to the phone), "¿Puedo dejar un mensaje?" (Can I leave a message?), "Te llamo luego" (I will call you later), "Perdón, no te oigo bien" (Sorry, I cannot hear you well).',words:[['¿Diga?','Hello? (answering in Spain)','Hello? (phone par)','dee-ga','ہیلو? (فون پر)'],['¿Está Sara?','Is Sara there?','Kya Sara hai?','es-ta sah-ra','کیا سارہ ہے?'],['Soy Farrakh','It is Farrakh (speaking)','Main Farrakh bol raha hoon','soy','میں فرخ بول رہا ہوں'],['Un momento','One moment','Ek minute','oon mo-men-to','ایک منٹ'],['ahora se pone','she/he is coming now','Woh abhi aata/aati hai','ah-oh-ra seh po-neh','وہ ابھی آٹا / آتی ہے'],['¿Puedo dejar un mensaje?','Can I leave a message?','Kya main paighaam chor sakta hoon?','pweh-do deh-har oon men-sah-heh','کیا میں پیغام چھوڑ سکتا ہوں?'],['Te llamo luego','I will call you later','Main baad mein call karunga','teh yah-mo lweh-go','میں بعد میں کال کروں گا'],['No te oigo bien','I cannot hear you well','Aap ki awaaz saaf nahi','no teh oy-go bee-en','آپ کی آواز صاف نہیں'],['¿Puedes repetir?','Can you repeat?','Kya dobara keh sakte hain?','pweh-des reh-peh-teer','کیا دوبارہ کہہ سکتے ہیں?'],['la cobertura','phone signal coverage','Signal ki range','ko-ber-too-ra','سگنل کی رینج'],['se ha cortado','it got cut off','Call kat gayi','seh ah kor-tah-do','کال کٹ گئی'],['¿Me oyes ahora?','Can you hear me now?','Ab awaaz aa rahi hai?','meh oh-yes ah-oh-ra','اب آواز آ رہی ہے?']],sents:[['¿Diga? Soy Farrakh. ¿Está Ahmed?','Hello? It is Farrakh. Is Ahmed there?','Hello? Main Farrakh. Kya Ahmed hai?'],['Perdón, no te oigo bien. ¿Puedes repetir?','Sorry, I cannot hear you well. Can you repeat?','Maafi, awaaz saaf nahi. Dobara keh dein?'],['Te llamo luego, ahora no tengo cobertura.','I will call you later, I have no signal now.','Main baad mein call karunga, abhi signal nahi.']],dlg:[['A','¿Diga?','Hello?'],['B','Hola, soy Farrakh. ¿Está Sara?','Hi, it is Farrakh. Is Sara there?'],['A','Un momento, ahora se pone.','One moment, she is coming.'],['B','Gracias.','Thanks.'],['A','Perdón, se ha cortado. ¿Me oyes ahora?','Sorry, it got cut off. Can you hear me now?']],quiz:[['Answering the phone in Spain you say...',['¿Diga?','¿Dónde?','¿Cuenta?','¿Cómo?'],0,'¿Diga? = Hello? (from decir, to say).'],['"Te llamo luego" means...',['Call me now','I will call you later','I called you','You call him'],1,'Luego = later (baad mein).'],['"No te oigo bien" means...',['I cannot see you','I cannot hear you well','I do not know you','I cannot come'],1,'Oír = to hear.'],['"Se ha cortado" means...',['It is expensive','It got cut off','It is late','It is broken'],1,'The call dropped (call kat gayi).'],['"¿Puedo dejar un mensaje?" asks...',['Can I call later?','Can I leave a message?','Can I speak?','Can I pay?'],1,'Dejar un mensaje = leave a message.']]},
{n:26,t:'Celebrations & Guests',sub:'Birthdays, weddings and hosting guests',ex:'Celebration words: la fiesta (party), el cumpleaños (birthday), la boda (wedding), el invitado (guest). Say "¡Felicidades!" (Congratulations!) for almost everything happy. Welcoming guests: "¡Bienvenidos a mi casa!" (Welcome to my home!), "Pasa, por favor" (Come in, please), "¿Quieres té o café?" Hosting tip from home: in Spain, like in Pakistan, guests are an honour — "Mi casa es tu casa" (My house is your house).',words:[['la fiesta','party / celebration','Dawat / party','fee-es-ta','دعوت  /  پارٹی'],['el cumpleaños','birthday','Salgirah','koom-pleh-an-yos','سالگرہ'],['¡Feliz cumpleaños!','Happy birthday!','Salgirah mubarak!','feh-lees koom-pleh-an-yos','سالگرہ مبارک!'],['la boda','wedding','Shaadi','bo-da','شادی'],['el invitado','guest (male)','Mehmaan','een-vee-tah-do','مہمان'],['¡Bienvenidos!','Welcome! (to guests)','Khush aamdeed!','bee-en-veh-nee-dos','خوش آمدید!'],['Pasa, por favor','Come in, please','Andar aayein','pah-sa por fah-vor','اندر آئیں'],['Mi casa es tu casa','My house is your house','Mera ghar aap ka ghar hai','mee kah-sa es too kah-sa','میرا گھر آپ کا گھر ہے'],['¡Felicidades!','Congratulations!','Mubarak ho!','feh-lee-see-dah-des','مبارک ہو!'],['el regalo','gift / present','Tohfa','reh-gah-lo','تحفہ'],['brindar','to make a toast','Khushi mein toast karna','breen-dar','خوشی میں ٹوسٹ کرنا'],['¡Que lo pases bien!','Have a great time!','Khoob maza karo!','keh lo pah-ses bee-en','خوب مزہ کرو!']],sents:[['¡Feliz cumpleaños! Este regalo es para ti.','Happy birthday! This gift is for you.','Salgirah mubarak! Yeh tohfa aap ke liye hai.'],['Bienvenidos a mi casa. Pasad, por favor.','Welcome to my home. Come in, please.','Mere ghar khush aamdeed. Andar aayein.'],['La boda es el sábado que viene.','The wedding is next Saturday.','Shaadi agle Haftay hai.']],dlg:[['A','¡Feliz cumpleaños, Sara!','Happy birthday, Sara!'],['B','¡Muchas gracias! Pasa, por favor.','Thank you very much! Come in, please.'],['A','Este regalo es para ti.','This gift is for you.'],['B','¡Qué bonito! ¿Quieres té o café?','How lovely! Do you want tea or coffee?'],['A','Un té, por favor. ¡Felicidades!','A tea, please. Congratulations!']],quiz:[['"La boda" means...',['The birthday','The wedding','The party','The gift'],1,'Boda = wedding (shaadi).'],['"Pasa, por favor" means...',['Pass the salt','Come in, please','Sit down','Wait here'],1,'Pasar = to come in/pass.'],['Guest in Spanish: ',['el regalo','el invitado','la fiesta','el brindis'],1,'Invitado = guest (mehmaan).'],['"¡Felicidades!" means...',['Goodbye!','Congratulations!','Good luck!','Welcome!'],1,'Felicidades = mubarak ho.'],['Gift is...',['el regalo','la boda','el cumpleaños','el invitado'],0,'Regalo = gift (tohfa).']]},
{n:27,t:'Complaints Politely',sub:'Fixing problems without a fight',ex:'Things go wrong when you travel — complain politely and Spanish people will help fast. Start soft: "Perdón, hay un problema" (Sorry, there is a problem). Useful lines: "No funciona" (It does not work), "Está roto" (It is broken), "Esto no es lo que pedí" (This is not what I ordered), "¿Puede cambiarlo?" (Can you change it?), "Quiero hablar con el encargado" (I want to speak to the manager). Stay calm and smile — "por favor" works magic.',words:[['hay un problema','there is a problem','Ek masla hai','ay oon pro-bleh-ma','ایک مسئلہ ہے'],['No funciona','It does not work','Yeh kaam nahi karta','no foon-see-oh-na','یہ کام نہیں کرتا'],['Está roto','It is broken','Yeh toota hua hai','es-ta roh-to','یہ ٹوٹا ہوا ہے'],['Esto no es lo que pedí','This is not what I ordered','Yeh woh nahi jo main ne mangwaya','es-to no es lo keh peh-dee','یہ وہ نہیں جو میں نے منگوایا'],['¿Puede cambiarlo?','Can you change it?','Kya aap isay badal sakte hain?','pweh-deh kam-bee-ar-lo','کیا آپ اسے بادل سکتے ہیں?'],['el encargado','the manager / person in charge','Manager / zimmedar','en-kar-gah-do','مینیجر  /  ذمہ دار'],['Perdón, está frío','Sorry, it is cold (food)','Maafi, yeh thanda hai','per-don es-ta free-oh','معافی, یہ ٹھنڈا ہے'],['Hay un error en la cuenta','There is a mistake in the bill','Bill mein ghalti hai','ay oon eh-ror en lah kwen-ta','بل میں غلطی ہے'],['¿Puede arreglarlo?','Can you fix it?','Kya aap isay theek kar sakte hain?','pweh-deh ah-rreh-glar-lo','کیا آپ اسے ٹھیک کر سکتے ہیں?'],['Lo antes posible','As soon as possible','Jitni jaldi ho sakay','lo an-tes po-see-bleh','جتنی جلدی ہو سکے'],['No estoy contento','I am not happy (with this)','Main mutmain nahi hoon','no es-toy kon-ten-to','میں مطمئن نہیں ہوں'],['Gracias por su ayuda','Thank you for your help','Aap ki madad ka shukriya','gra-see-as por soo ah-yoo-da','آپ کی مدد کا شکریہ']],sents:[['Perdón, hay un problema: la ducha no funciona.','Sorry, there is a problem: the shower does not work.','Maafi, ek masla hai: shower kaam nahi karta.'],['Esto no es lo que pedí. Pedí pollo, no pescado.','This is not what I ordered. I ordered chicken, not fish.','Yeh woh nahi jo mangwaya. Main ne chicken mangwaya tha, machli nahi.'],['Hay un error en la cuenta, por favor.','There is a mistake in the bill, please.','Bill mein ghalti hai, meherbani karke dekhein.']],dlg:[['A','Perdón, hay un problema con mi habitación.','Sorry, there is a problem with my room.'],['B','¿Qué pasa?','What is the matter?'],['A','El aire no funciona y está roto el grifo.','The air conditioning does not work and the tap is broken.'],['B','Lo siento mucho. Lo arreglo hoy, o le cambio de habitación.','I am very sorry. I will fix it today, or change your room.'],['A','Gracias por su ayuda.','Thank you for your help.']],quiz:[['"No funciona" means...',['It is new','It does not work','It is closed','It is mine'],1,'Funcionar = to work/function.'],['"Está roto" means...',['It is broken','It is cold','It is ready','It is small'],0,'Roto = broken (toota hua).'],['Manager in Spanish: ',['el encargado','el invitado','el cliente','el cocinero'],0,'Encargado = person in charge.'],['"Hay un error en la cuenta" means...',['The bill is cheap','There is a mistake in the bill','The bill is ready','I lost the bill'],1,'Error = mistake (ghalti).'],['The polite starter for a complaint is...',['¡Escucha!','Perdón, hay un problema','Rápido, por favor','Esto es malo'],1,'Soft start + por favor = help comes fast.']]},
{n:28,t:'My Village & City',sub:'Talking about where YOU live',ex:'Now talk about your own home — Chak No. 18 Janoobi! Places: el pueblo (village), la ciudad (city), el campo (countryside/fields), la mezquita (mosque), la escuela (school), el mercado (market). Describe: "Mi pueblo es pequeño y tranquilo" (My village is small and quiet), "Vivo cerca de..." (I live near...), "En mi pueblo hay..." (In my village there is...). People love hearing about your home — this is your best conversation topic!',words:[['mi pueblo','my village','Mera gaon','mee pweh-blo','میرا گاؤں'],['la ciudad','city','Sheher','see-oo-dad','شہر'],['el campo','countryside / fields','Khet / dehat','kam-po','کھیت  /  دیہات'],['Vivo en un pueblo','I live in a village','Main gaon mein rehta hoon','vee-vo en oon pweh-blo','میں گاؤں میں رہتا ہوں'],['Es pequeño y tranquilo','It is small and quiet','Yeh chota aur pur-sukoon hai','es peh-ken-yo ee tran-kee-lo','یہ چھوٹا اور پرسکون ہے'],['la mezquita','mosque','Masjid','mes-kee-ta','مسجد'],['la escuela','school','School','es-kweh-la','اسکول'],['el río','river','Darya','ree-oh','دریا'],['los campos de trigo','wheat fields','Gandum ke khet','kam-pos deh tree-go','گندم کے کھیت'],['La gente es amable','People are kind','Log meherbaan hain','lah hen-teh es ah-mah-bleh','لوگ مہربان ہیں'],['Está en Punjab','It is in Punjab','Yeh Punjab mein hai','es-ta en','یہ پنجاب میں ہے'],['Mi lugar favorito','My favourite place','Meri pasandeeda jagah','mee loo-gar fah-vo-ree-to','میری پسندیدہ جگہ']],sents:[['Vivo en un pueblo pequeño de Punjab, en Pakistán.','I live in a small village in Punjab, Pakistan.','Main Pakistan ke Punjab ke ek chotay gaon mein rehta hoon.'],['En mi pueblo hay una mezquita, una escuela y un mercado.','In my village there is a mosque, a school and a market.','Mere gaon mein ek masjid, ek school aur ek bazaar hai.'],['La gente de mi pueblo es muy amable.','The people of my village are very kind.','Mere gaon ke log bohat meherbaan hain.']],dlg:[['A','¿Dónde vives, Farrakh?','Where do you live, Farrakh?'],['B','Vivo en un pueblo de Punjab, en Pakistán. Se llama Chak 18.','I live in a village in Punjab, Pakistan. It is called Chak 18.'],['A','¿Cómo es tu pueblo?','What is your village like?'],['B','Es pequeño y tranquilo. Hay campos de trigo y la gente es amable.','It is small and quiet. There are wheat fields and the people are kind.'],['A','¡Qué bonito!','How lovely!']],quiz:[['"Mi pueblo" means...',['My city','My village','My house','My country'],1,'Pueblo = village/town (gaon).'],['Mosque in Spanish: ',['la escuela','la mezquita','el mercado','la iglesia'],1,'Mezquita = mosque (masjid).'],['"La gente es amable" means...',['The food is good','The people are kind','The place is big','The weather is fine'],1,'Gente = people, amable = kind.'],['Fields/countryside is...',['el campo','el río','el trigo solo','la ciudad'],0,'Campo = fields/countryside.'],['"Es pequeño y tranquilo" describes...',['A big noisy city','A small quiet place','An expensive hotel','A fast train'],1,'Pequeño = small, tranquilo = quiet.']]},
{n:29,t:'Hopes & Dreams',sub:'Quiero, espero, un día... — your future',ex:'Talk about your dreams with three magic verbs: QUIERO (I want), ESPERO (I hope), VOY A (I am going to). "Quiero aprender español" (I want to learn Spanish), "Espero viajar a España un día" (I hope to travel to Spain one day), "Mi sueño es..." (My dream is...). Add reasons with "para" (in order to): "Estudio para trabajar y ayudar a mi familia" (I study in order to work and help my family). Dreams in Spanish sound beautiful — say yours aloud!',words:[['mi sueño','my dream','Mera khwab / sapna','mee swen-yo — ñ = ny','میرا خواب  /  سپنا'],['Quiero aprender','I want to learn','Main seekhna chahta hoon','kee-eh-ro ah-pren-der','میں سیکھنا چاہتا ہوں'],['Espero viajar','I hope to travel','Mujhe ummeed hai main safar karunga','es-peh-ro vee-ah-har','مجھے امید ہے میں سفر کروں گا'],['un día','one day','Ek din','oon dee-a','ایک دن'],['en el futuro','in the future','Mustaqbil mein','en el foo-too-ro','مستقبل میں'],['Quiero trabajar','I want to work','Main kaam karna chahta hoon','kee-eh-ro tra-bah-har','میں کام کرنا چاہتا ہوں'],['para ayudar a mi familia','to help my family','Apne khandan ki madad ke liye','pah-ra ah-yoo-dar ah mee fah-mee-lee-a','اپنے خاندان کی مدد کے لیے'],['Mi meta es...','My goal is...','Mera hadaf hai...','mee meh-ta es','میرا ہدف ہے...'],['con esfuerzo','with effort / hard work','Mehnat se','kon es-fwer-so','محنت سے'],['Nunca es tarde','It is never too late','Kabhi dair nahi hoti','noon-ka es tar-deh','کبھی دیر نہیں ہوتی'],['paso a paso','step by step','Qadam ba qadam','pah-so ah pah-so','قدم با قدم'],['¡Sí se puede!','Yes we can / it can be done!','Ho sakta hai!','see seh pweh-deh','ہو سکتا ہے!']],sents:[['Mi sueño es hablar español muy bien.','My dream is to speak Spanish very well.','Mera khwab hai ke main Spanish bohat achi bolun.'],['Espero viajar a España un día.','I hope to travel to Spain one day.','Mujhe ummeed hai ek din Spain jaunga.'],['Estudio todos los días para ayudar a mi familia.','I study every day to help my family.','Main har roz apne khandan ki madad ke liye parhta hoon.']],dlg:[['A','¿Cuál es tu sueño, Farrakh?','What is your dream, Farrakh?'],['B','Mi sueño es hablar español y viajar a España.','My dream is to speak Spanish and travel to Spain.'],['A','¿Y tu meta para este año?','And your goal for this year?'],['B','Quiero terminar el nivel A2, paso a paso.','I want to finish level A2, step by step.'],['A','¡Sí se puede!','Yes you can!']],quiz:[['"Mi sueño" means...',['My house','My dream','My job','My plan B'],1,'Sueño = dream (khwab).'],['"Espero viajar" means...',['I travel a lot','I hope to travel','I travelled','I hate travel'],1,'Espero = I hope (ummeed hai).'],['Goal in Spanish: ',['la meta','el sueño roto','el paso','el futuro total'],0,'Meta = goal (hadaf).'],['"Nunca es tarde" means...',['It is never too late','It is always late','Never say it','Tomorrow is late'],0,'A phrase to remember on hard days.'],['"Paso a paso" means...',['Very fast','Step by step','One day','With money'],1,'Paso = step (qadam).']]},
{n:30,t:'Story Telling',sub:'Past + future mixed — tell your story!',ex:'A real story mixes tenses: past for what happened, future for what comes next. Story glue words: primero (first), luego (then), después (after that), de repente (suddenly), al final (in the end), y entonces (and then/so). Try your own story: "Ayer fui al mercado. Compré té. Luego, de repente, vi a un amigo. Mañana voy a visitarlo." You now have everything — this is the final A2 lesson. ¡Tu historia empieza ahora! (Your story starts now!)',words:[['primero','first (in a story)','Pehle','pree-meh-ro','پہلے'],['luego','then','Phir','lweh-go','پھر'],['después','afterwards','Us ke baad','des-pwes','اس کے بعد'],['de repente','suddenly','Achanak','deh reh-pen-teh','اچانک'],['al final','in the end','Aakhir mein','al fee-nal','آخر میں'],['y entonces','and then / so','Aur phir','ee en-ton-ses','اور پھر'],['había una vez','once upon a time','Ek tha / ek dafa ka zikr hai','ah-bee-a oo-na ves','ایک تھا  /  ایک دفعہ کا ذکر ہے'],['la historia','story / history','Kahani','ees-toh-ree-a','کہانی'],['me pasó','it happened to me','Mere saath hua','meh pah-so','میرے ساتھ ہوا'],['¡No me digas!','No way! / You don\'t say!','Acha?! Sach mein?!','no meh dee-gas','اچھا?! سچ میں?!'],['¡Qué suerte!','What luck!','Kitni khush-qismati!','keh swer-teh','کتنی خوش قسمتی!'],['continuará...','to be continued...','Jaari hai...','kon-tee-noo-ah-ra','جاری ہے...']],sents:[['Ayer fui al mercado y, de repente, vi a un viejo amigo.','Yesterday I went to the market and, suddenly, I saw an old friend.','Kal main bazaar gaya aur achanak ek purana dost mila.'],['Primero estudié, luego trabajé y al final descansé.','First I studied, then I worked and in the end I rested.','Pehle main ne parha, phir kaam kiya aur aakhir mein aaram kiya.'],['El año que viene voy a contar esta historia en España.','Next year I am going to tell this story in Spain.','Agle saal main yeh kahani Spain mein sunaunga.']],dlg:[['A','Cuéntame: ¿qué te pasó ayer?','Tell me: what happened to you yesterday?'],['B','Fui a la ciudad. Primero compré un móvil nuevo.','I went to the city. First I bought a new phone.'],['A','¿Y luego?','And then?'],['B','De repente, ¡vi a mi primo! Comimos juntos.','Suddenly, I saw my cousin! We ate together.'],['A','¡Qué suerte! ¿Y mañana?','What luck! And tomorrow?'],['B','Mañana voy a visitarlo en su casa. ¡La historia continúa!','Tomorrow I am going to visit him at his house. The story continues!']],quiz:[['"De repente" means...',['Slowly','Suddenly','Finally','First'],1,'De repente = suddenly (achanak).'],['"Al final" means...',['At the start','In the end','Tomorrow','Suddenly'],1,'Al final = in the end (aakhir mein).'],['"Había una vez..." starts...',['A question','A story (once upon a time)','A complaint','A goodbye'],1,'The classic story opening.'],['Which sentence mixes past and future correctly?',['Ayer voy al mercado','Mañana fui al mercado','Ayer fui al mercado y mañana voy a volver','Fui mañana al mercado'],2,'Fui = past (went), voy a volver = future (going to return).'],['"¡No me digas!" means...',['Do not speak','No way! / Really?!','Tell me everything','I do not know'],1,'A fun reaction — like "Acha?! Sach mein?!"']]}
);


/* ── LAYER 1 · CONTENT (continued) ── */
/* ============ LESSONS 31-40 (B1 PACK) ============ */
LESSONS.push(
{n:31,t:'Por vs Para',sub:'Two little words, one clear rule',ex:'POR and PARA both translate "for" — but Spanish keeps them apart. POR = through, along, because of, exchange, duration: "paseo por el parque" (I walk through the park), "gracias por tu ayuda" (thanks FOR your help), "por la mañana" (in the morning). PARA = destination, purpose, deadline, opinion: "salgo para Lahore" (I leave FOR Lahore), "estudio para aprender" (I study IN ORDER TO learn), "para mañana" (by tomorrow), "para mí" (for me / in my opinion). Easy memory hook: PARA points forward to a goal; POR passes through a cause or a place.',words:[['por la mañana','in the morning','Subah ko','por lah man-yah-na','صبح کو'],['gracias por...','thank you for...','... ke liye shukriya','gra-see-as por','کے لیے شکریہ'],['para mí','for me / in my opinion','Mere liye / meri raaye mein','pah-ra mee','میرے لیے / میری رائے میں'],['para mañana','by tomorrow (deadline)','Kal tak ke liye','pah-ra man-yah-na','کل تک کے لیے'],['pasear por el parque','to walk through the park','Park mein sair karna','pah-seh-ar por el par-keh','پارک میں سیر کرنا'],['por eso','that is why / so','Isi liye','por eh-so','اسی لیے'],['para aprender','in order to learn','Seekhne ke liye','pah-ra ah-pren-der','سیکھنے کے لیے'],['por favor, pasa por aquí','please, come through here','Meherbani, idhar se aayein','por fah-vor pah-sa por ah-kee','مہربانی، ادھر سے آئیں'],['un regalo para ti','a gift for you','Aap ke liye tohfa','oon reh-gah-lo pah-ra tee','آپ کے لیے تحفہ'],['por la tarde','in the afternoon','Dopahar ko','por lah tar-deh','دوپہر کو'],['viajar por España','to travel around Spain','Spain mein ghumna','vee-ah-har por es-pan-ya','اسپین میں گھومنا'],['para siempre','forever','Hamesha ke liye','pah-ra see-em-preh','ہمیشہ کے لیے']],sents:[['Estudio español para viajar a España.','I study Spanish (in order) to travel to Spain.','Main Spain jane ke liye Spanish seekh raha hoon.'],['Gracias por tu ayuda, amigo.','Thank you for your help, friend.','Aap ki madad ke liye shukriya, dost.'],['Paseo por el pueblo por la mañana.','I walk through the village in the morning.','Main subah gaon mein sair karta hoon.']],dlg:[['A','¿Por qué estudias español?','Why do you study Spanish?'],['B','Estudio para trabajar y para viajar por España.','I study (in order) to work and to travel around Spain.'],['A','¿Y este libro? ¿Es para mí?','And this book? Is it for me?'],['B','Sí, es para ti. ¡Y gracias por tu ayuda ayer!','Yes, it is for you. And thank you for your help yesterday!']],quiz:[['"Un regalo ___ ti" (a gift FOR you — destination):',['por','para','de','en'],1,'A gift with a receiver = PARA. POR passes through.'],['"Gracias ___ tu ayuda":',['para','por','a','con'],1,'Thanks FOR a cause/reason = POR: gracias por...'],['"Estudio ___ aprender" (in order to):',['por','para','en','sin'],1,'Purpose (in order to) = PARA + infinitive.'],['"Paseo ___ el parque" (through):',['para','por','hasta','sobre'],1,'Moving through a place = POR.'],['"Lo necesito ___ mañana" (by tomorrow — deadline):',['por','para','desde','en'],1,'Deadlines = PARA.']]},
{n:32,t:'Two Pasts — Preterite vs Imperfect',sub:'What happened vs how it was',ex:'Spanish has TWO past tenses and choosing is simpler than it sounds. PRETERITE = finished actions with a clear end: "Ayer comí en casa" (Yesterday I ate at home — done!). IMPERFECT = how things were / used to be / background: "De niño, comía en casa de mi abuela" (As a child, I used to eat at my grandmother\'s). Imperfect regular endings: -ar: -aba, -abas, -aba... (hablaba); -er/-ir: -ía, -ías, -ía... (comía, vivía). Only 3 irregulars: ser (era), ir (iba), ver (veía). In stories: imperfect sets the scene, preterite moves the action: "Hacía sol cuando salí" (It was sunny [scene] when I left [action]).',words:[['hablaba','I used to speak / I was speaking','Main bola karta tha','ah-blah-ba','میں بولا کرتا تھا'],['comía','I used to eat / I was eating','Main khaya karta tha','ko-mee-a','میں کھایا کرتا تھا'],['era','I/he/she was (description, imperfect)','Tha / thi (halat)','eh-ra','تھا / تھی'],['iba','I used to go / I was going','Main jaya karta tha','ee-ba','میں جایا کرتا تھا'],['de niño','as a child','Bachpan mein','deh neen-yo','بچپن میں'],['siempre','always (habit in the past)','Hamesha','see-em-preh','ہمیشہ'],['cuando era joven','when I was young','Jab main jawan tha','kwan-do eh-ra ho-ven','جب میں جوان تھا'],['hacía sol','it was sunny (background)','Dhoop thi','ah-see-a sol','دھوپ تھی'],['mientras','while','Jab ke / is dauran','mee-en-tras','جبکہ / اس دوران'],['de repente pasó','suddenly it happened','Achanak hua','deh reh-pen-teh pah-so','اچانک ہوا'],['todos los días (antes)','every day (back then)','Har roz (pehle zamaane mein)','to-dos los dee-as an-tes','ہر روز (پہلے زمانے میں)'],['vivíamos en el pueblo','we lived (used to live) in the village','Hum gaon mein raha karte thay','vee-vee-ah-mos en el pweh-blo','ہم گاؤں میں رہا کرتے تھے']],sents:[['De niño, jugaba en los campos todos los días.','As a child, I used to play in the fields every day.','Bachpan mein main har roz kheton mein khela karta tha.'],['Hacía calor cuando llegamos a la ciudad.','It was hot when we arrived in the city.','Jab hum sheher pohanchay to garmi thi.'],['Ayer visité a mi abuela; ella cocinaba muy bien de joven.','Yesterday I visited my grandmother; she used to cook very well when young.','Kal main dadi se mila; woh jawani mein bohat acha khana pakaya karti thin.']],dlg:[['A','Cuéntame de tu infancia. ¿Dónde vivías?','Tell me about your childhood. Where did you live?'],['B','Vivía en un pueblo pequeño. Jugaba en el río y ayudaba a mi padre.','I lived in a small village. I used to play in the river and help my father.'],['A','¿Y qué pasó ayer? Te vi en la ciudad.','And what happened yesterday? I saw you in the city.'],['B','Ayer fui a visitar a mi abuela. ¡Estaba muy contenta!','Yesterday I went to visit my grandmother. She was very happy!']],quiz:[['"De niño, yo ___ al fútbol" (habit, used to):',['jugué','jugaba','jugaré','juego'],1,'Habits in the past = imperfect: jugaba.'],['"Ayer ___ a mi primo" (finished action yesterday):',['veía','iba','vi','era'],2,'One finished action = preterite: vi (I saw).'],['The imperfect of "comer" (yo) is...',['comí','comía','comeré','como'],1,'-er imperfect: comía.'],['"Hacía sol cuando salí" — the scene-setter is...',['salí','cuando','hacía sol','yo'],2,'Weather background = imperfect (hacía). Salí is the action.'],['"Era" is the imperfect of...',['ir','ver','ser','estar'],2,'Ser → era. Ir → iba. Ver → veía. Only 3 irregulars!']]},
{n:33,t:'Gustar & Verbs Like It',sub:'Me gusta, me encanta, me duele...',ex:'GUSTAR works backwards: "Me gusta el té" literally = "Tea is pleasing to me". The verb changes with the THING: gusta (one thing / verb) — gustan (many things): "Me gustan los mangos". Strength ladder: no me gusta (I do not like) → me gusta (I like) → me gusta mucho → ¡me encanta! (I love it!). The same pattern runs a whole family: me duele (it hurts me), me interesa (it interests me), me falta (I am missing / I lack), me queda (I have left / it suits me), me parece (it seems to me). People words sit in front: a mí (me), a ti (you), a Ahmed le gusta...',words:[['me gusta','I like (one thing)','Mujhe pasand hai','meh goos-ta','مجھے پسند ہے'],['me gustan','I like (several things)','Mujhe (kai cheezein) pasand hain','meh goos-tan','مجھے پسند ہیں'],['¡me encanta!','I love it!','Mujhe bohat bohat pasand hai!','meh en-kan-ta','مجھے بہت بہت پسند ہے!'],['no me gusta nada','I do not like it at all','Mujhe bilkul pasand nahi','no meh goos-ta nah-da','مجھے بالکل پسند نہیں'],['me interesa','it interests me','Mujhe is mein dilchaspi hai','meh een-teh-reh-sa','مجھے اس میں دلچسپی ہے'],['me falta...','I am missing / I need...','Mujhe ... ki kami hai','meh fal-ta','مجھے ۔۔۔ کی کمی ہے'],['me queda bien','it suits me / fits me','Yeh mujh par jachta hai','meh keh-da bee-en','یہ مجھ پر جچتا ہے'],['me parece bien','it seems good to me','Mujhe theek lagta hai','meh pah-reh-seh bee-en','مجھے ٹھیک لگتا ہے'],['¿te gusta...?','do you like...?','Kya aap ko ... pasand hai?','teh goos-ta','کیا آپ کو ۔۔۔ پسند ہے؟'],['le gusta','he/she likes','Usay pasand hai','leh goos-ta','اسے پسند ہے'],['me duelen los pies','my feet hurt','Mere paon mein dard hai','meh dweh-len los pee-es','میرے پاؤں میں درد ہے'],['a mí también','me too (liking)','Mujhe bhi','ah mee tam-bee-en','مجھے بھی']],sents:[['Me gustan mucho los mangos de mi pueblo.','I like the mangoes of my village a lot.','Mujhe apne gaon ke aam bohat pasand hain.'],['¿Te interesa aprender urdu? A mí me encanta enseñar.','Are you interested in learning Urdu? I love teaching.','Kya aap ko Urdu seekhne mein dilchaspi hai? Mujhe sikhana bohat pasand hai.'],['Me falta tiempo, pero me parece bien el plan.','I lack time, but the plan seems good to me.','Mujhe waqt ki kami hai, lekin plan mujhe theek lagta hai.']],dlg:[['A','¿Te gusta la comida española?','Do you like Spanish food?'],['B','¡Me encanta! Me gustan mucho las tapas. ¿Y a ti?','I love it! I like tapas a lot. And you?'],['A','A mí me gusta, pero me duele el estómago con el picante.','I like it, but my stomach hurts with spicy food.'],['B','¡Qué pena! ¿Te interesa más la comida suave?','What a shame! Are you more interested in mild food?']],quiz:[['"I like the books" = ...',['Me gusta los libros','Me gustan los libros','Me gustas los libros','Gusto los libros'],1,'Plural thing → gustan.'],['"¡Me encanta!" means...',['I like it a little','I love it!','I hate it','It hurts me'],1,'Encantar = stronger than gustar: I love it!'],['"Me duele la cabeza" uses the same pattern as gustar and means...',['I like my head','My head hurts','I wash my head','My head is big'],1,'Doler: me duele = it hurts me.'],['"He likes tea" = ...',['Él gusta el té','Le gusta el té','Se gusta el té','Lo gusta el té'],1,'For he/she use "le gusta".'],['"Me falta dinero" means...',['I have lots of money','I am missing money / I lack money','I love money','I lost money yesterday'],1,'Faltar = to be lacking: me falta = I lack.']]},
{n:34,t:'Reflexive Verbs — My Day, Deep',sub:'Me levanto, me ducho, me acuesto...',ex:'When the action comes back to YOU, Spanish adds a mirror word: me, te, se, nos, os, se. LEVANTARSE (to get up): me levanto, te levantas, se levanta, nos levantamos, os levantáis, se levantan. The mirror word matches the person and sits BEFORE the verb. Daily set: despertarse (wake up — e→ie: me despierto), ducharse (shower), vestirse (get dressed — e→i: me visto), sentarse (sit — e→ie: me siento), acostarse (go to bed — o→ue: me acuesto), dormirse (fall asleep), llamarse (be called), quedarse (stay), irse (leave/go away). Tell your whole day with these!',words:[['me levanto a las seis','I get up at six','Main chhe bajay uthta hoon','meh leh-van-to ah las seys','میں چھ بجے اٹھتا ہوں'],['me despierto','I wake up','Main jaagta hoon','meh des-pee-er-to','میں جاگتا ہوں'],['me ducho','I shower','Main nahata hoon','meh doo-cho','میں نہاتا ہوں'],['me visto','I get dressed','Main kapray pehenta hoon','meh vees-to','میں کپڑے پہنتا ہوں'],['me siento','I sit down','Main baithta hoon','meh see-en-to','میں بیٹھتا ہوں'],['me acuesto','I go to bed','Main sonay jata hoon','meh ah-kwes-to','میں سونے جاتا ہوں'],['me duermo','I fall asleep','Mujhe neend aa jati hai','meh dwer-mo','مجھے نیند آ جاتی ہے'],['se llama','he/she is called','Us ka naam hai','seh yah-ma','اس کا نام ہے'],['me quedo en casa','I stay at home','Main ghar par rehta hoon','meh keh-do en kah-sa','میں گھر پر رہتا ہوں'],['bañarse','to bathe','Nahana','ban-yar-seh','نہانا'],['afeitarse','to shave','Daarhi banana / shave karna','ah-fey-tar-seh','داڑھی بنانا'],['peinarse','to comb your hair','Kanghi karna','pey-nar-seh','کنگھی کرنا']],sents:[['Me despierto a las cinco, pero me levanto a las cinco y media.','I wake up at five, but I get up at half past five.','Main paanch bajay jaagta hoon, lekin saarhay paanch uthta hoon.'],['Después de trabajar, me ducho y me acuesto temprano.','After working, I shower and go to bed early.','Kaam ke baad main nahata hoon aur jaldi so jata hoon.'],['Mi abuela se levanta muy temprano todos los días.','My grandmother gets up very early every day.','Meri dadi har roz bohat sawere uthti hain.']],dlg:[['A','¿A qué hora te levantas?','What time do you get up?'],['B','Me despierto a las cinco y me levanto a las cinco y media. ¿Y tú?','I wake up at five and get up at half past five. And you?'],['A','Yo me levanto a las siete. Me ducho rápido y me visto.','I get up at seven. I shower quickly and get dressed.'],['B','¿Y por la noche?','And at night?'],['A','Me acuesto a las diez y me duermo enseguida.','I go to bed at ten and fall asleep right away.']],quiz:[['"Me levanto" — the "me" shows...',['a question','the action comes back to me (reflexive)','the past tense','a plural'],1,'Reflexive: the action returns to the doer.'],['"She gets dressed" = ...',['Se visten','Te vistes','Se viste','Se visto'],2,'Ella → se + viste (vestirse e→i).'],['"Me acuesto" has o→ue. It means...',['I wake up','I go to bed','I sit down','I get up'],1,'Acostarse = go to bed; me acuesto.'],['"We stay at home" = ...',['Se quedamos','Nos quedamos en casa','Me quedo en casa','Nos queda en casa'],1,'Nosotros → nos quedamos.'],['Which verb is NOT reflexive here?',['ducharse','comer','acostarse','levantarse'],1,'Comer is a normal verb. The others carry -se.']]},
{n:35,t:'Giving Opinions & Agreeing',sub:'Creo que sí, estoy de acuerdo...',ex:'Opinions start with soft openers: creo que... (I think that...), pienso que... (I think...), me parece que... (it seems to me that...), en mi opinión... (in my opinion...), para mí... (for me...). Agree: ¡Claro! (Of course!), estoy de acuerdo (I agree), tienes razón (you are right), ¡exacto!, yo también (me too). Disagree politely: no estoy de acuerdo (I do not agree), yo tampoco (me neither), no creo (I do not think so), bueno, depende... (well, it depends...). Opinion + porque = a real conversation: "Creo que el español es útil porque abre puertas."',words:[['creo que...','I think that...','Mera khayal hai ke...','kreh-oh keh','میرا خیال ہے کہ'],['en mi opinión','in my opinion','Meri raaye mein','en mee oh-pee-nee-on','میری رائے میں'],['estoy de acuerdo','I agree','Main muttafiq hoon','es-toy deh ah-kwer-do','میں متفق ہوں'],['tienes razón','you are right','Aap theek kehte hain','tee-eh-nes rah-son','آپ ٹھیک کہتے ہیں'],['no estoy de acuerdo','I do not agree','Main muttafiq nahi hoon','no es-toy deh ah-kwer-do','میں متفق نہیں ہوں'],['yo también','me too','Main bhi / mujhe bhi','yo tam-bee-en','میں بھی'],['yo tampoco','me neither','Main bhi nahi','yo tam-po-ko','میں بھی نہیں'],['depende','it depends','Is par munhasir hai','deh-pen-deh','اس پر منحصر ہے'],['quizás','maybe / perhaps','Shayad','kee-sas','شاید'],['sin duda','without doubt / definitely','Bilkul yaqeenan','seen doo-da','بالکل یقیناً'],['por un lado... por otro','on one hand... on the other','Ek taraf... doosri taraf','por oon lah-do por oh-tro','ایک طرف ۔۔۔ دوسری طرف'],['al final','in the end / after all','Aakhir mein','al fee-nal','آخر میں']],sents:[['Creo que aprender español es una idea muy buena.','I think learning Spanish is a very good idea.','Mera khayal hai Spanish seekhna bohat acha khayal hai.'],['Estoy de acuerdo: la práctica diaria es la clave.','I agree: daily practice is the key.','Main muttafiq hoon: rozana mashq hi kunji hai.'],['Para mí, el té de Pakistán es el mejor del mundo.','For me, Pakistani tea is the best in the world.','Mere liye Pakistan ki chai duniya mein sab se best hai.']],dlg:[['A','En mi opinión, es mejor estudiar por la mañana. ¿Qué crees tú?','In my opinion, it is better to study in the morning. What do you think?'],['B','Estoy de acuerdo. Por la mañana la cabeza está fresca.','I agree. In the morning the head is fresh.'],['A','¿Y los fines de semana? ¿Estudias también?','And on weekends? Do you study too?'],['B','Depende. A veces sí, a veces descanso. ¡Pero el lunes sigo!','It depends. Sometimes yes, sometimes I rest. But on Monday I continue!']],quiz:[['"Estoy de acuerdo" means...',['I am tired','I agree','I am lost','I am sure'],1,'De acuerdo = in agreement (muttafiq).'],['"Tienes razón" means...',['You are late','You are right','You have a reason to pay','You are hungry'],1,'Tener razón = to be right.'],['A soft way to start an opinion: ',['¡Escucha!','Creo que...','Rápido','Silencio'],1,'Creo que... = I think that... — polite and natural.'],['"Yo tampoco" answers a negative like "No me gusta el frío": it means...',['Me too','Me neither','Me first','Not me'],1,'También = too (positive); tampoco = neither (negative).'],['"Depende" means...',['It is deep','It depends','It is expensive','It is decided'],1,'Depende = munhasir hai — it depends.']]}
);
LESSONS.push(
{n:36,t:'Phone, WhatsApp & Internet Deep',sub:'Messages, calls and data — modern life',ex:'Deep phone Spanish: RECARGAR (top up credit), el saldo (balance), quedarse sin batería (run out of battery), el cargador (charger), cobertura (signal coverage), datos móviles (mobile data), mandar / enviar (send), reenviar (forward), el grupo (group chat), el estado (WhatsApp status/story), silenciar (mute), bloquear (block), la contraseña (password), iniciar sesión (log in), descargar (download), subir (upload/share up). Useful cries for help: "Se me acabó el saldo" (My credit ran out), "¿Me pasas tu wifi?" (Can you share your Wi-Fi with me?), "Te mando mi ubicación" (I will send you my location).',words:[['recargar','to top up (credit)','Balance dalwana / recharge karna','reh-kar-gar','بیلنس ڈلوانا'],['el saldo','balance (phone credit)','Balance','sal-do','بیلنس'],['se me acabó la batería','my battery died','Meri battery khatam ho gayi','seh meh ah-kah-bo lah bah-teh-ree-a','میری بیٹری ختم ہو گئی'],['mandar un mensaje','to send a message','Paighaam bhejna','man-dar oon men-sah-heh','پیغام بھیجنا'],['el grupo de WhatsApp','the WhatsApp group','WhatsApp group','groo-po deh whats-app','واٹس ایپ گروپ'],['silenciar','to mute','Khamosh / mute karna','see-len-see-ar','خاموش کرنا'],['te mando mi ubicación','I will send you my location','Main apni location bhejta hoon','teh man-do mee oo-bee-kah-see-on','میں اپنی لوکیشن بھیجتا ہوں'],['¿me pasas el wifi?','can you share the Wi-Fi with me?','Kya aap wifi share kar dein ge?','meh pah-sas el wee-fee','کیا آپ وائی فائی شیئر کر دیں گے؟'],['iniciar sesión','to log in','Login karna','ee-nee-see-ar seh-see-on','لاگ ان کرنا'],['descargar','to download','Download karna','des-kar-gar','ڈاؤن لوڈ کرنا'],['sin conexión','no connection / offline','Connection nahi hai','seen ko-nek-see-on','کنیکشن نہیں ہے'],['guarda mi número','save my number','Mera number save kar lein','gwar-da mee noo-meh-ro','میرا نمبر سیو کر لیں']],sents:[['Se me acabó el saldo; tengo que recargar.','My credit ran out; I have to top up.','Mera balance khatam ho gaya; recharge karwana hai.'],['Te mando mi ubicación por WhatsApp, ¿vale?','I will send you my location on WhatsApp, okay?','Main WhatsApp par apni location bhejta hoon, theek hai?'],['En mi pueblo a veces no hay cobertura.','In my village sometimes there is no signal.','Mere gaon mein kabhi signal nahi hota.']],dlg:[['A','¿Tienes mi número nuevo?','Do you have my new number?'],['B','No. Mándame un WhatsApp y lo guardo.','No. Send me a WhatsApp and I will save it.'],['A','Ahora no puedo: se me acabó el saldo y no hay wifi.','Right now I cannot: my credit ran out and there is no Wi-Fi.'],['B','Te paso mi wifi. La contraseña es "sol123".','I will share my Wi-Fi. The password is "sol123".']],quiz:[['"Se me acabó la batería" means...',['I bought a battery','My battery died / ran out','My battery is new','I lost my charger'],1,'Acabarse = to run out/finish.'],['"Recargar" for a phone means...',['to call','to top up credit','to mute','to block'],1,'Recargar = recharge (balance dalwana).'],['"Te mando mi ubicación" = I will send you my...',['photo','location','password','group'],1,'Ubicación = location.'],['"Silenciar" means...',['to shout','to mute','to forward','to save'],1,'Silenciar = mute / make silent.'],['"Sin conexión" means...',['with signal','no connection','fast internet','free Wi-Fi'],1,'Sin = without, conexión = connection.']]},
{n:37,t:'At the Embassy & Official Work',sub:'Documents, appointments and formal Spanish',ex:'Official Spanish is formal: always USTED, and start with "Buenos días, vengo a..." (Good morning, I have come to...). Key words: el pasaporte (passport), el visado (visa), la cita (appointment), el formulario (form), rellenar (fill in), firmar (sign), el sello (stamp), el documento (document), la fotocopia (photocopy), el certificado (certificate), la entrevista (interview), el plazo (deadline/time limit). Questions that save you: "¿Qué documentos necesito?" (What documents do I need?), "¿Cuánto tarda?" (How long does it take?), "¿Dónde firmo?" (Where do I sign?). Take copies of everything — ¡siempre!',words:[['la cita','appointment (official)','Appointment / tay waqt','see-ta','اپائنٹمنٹ'],['el visado','visa','Visa','vee-sah-do','ویزا'],['rellenar el formulario','to fill in the form','Form bharna','reh-yeh-nar el for-moo-lah-ree-oh','فارم بھرنا'],['¿dónde firmo?','where do I sign?','Main kahan dastakhat karoon?','don-deh feer-mo','میں کہاں دستخط کروں؟'],['el sello','stamp / seal','Mohar / stamp','seh-yo','مہر / اسٹیمپ'],['la fotocopia','photocopy','Photocopy','foh-toh-koh-pee-a','فوٹو کاپی'],['¿cuánto tarda?','how long does it take?','Kitna waqt lagta hai?','kwan-to tar-da','کتنا وقت لگتا ہے؟'],['¿qué documentos necesito?','what documents do I need?','Mujhe kon se kagzaat chahiye?','keh doh-koo-men-tos neh-seh-see-to','مجھے کون سے کاغذات چاہیے؟'],['vengo a renovar...','I have come to renew...','Main ... renew karwane aaya hoon','ven-go ah reh-no-var','میں تجدید کروانے آیا ہوں'],['el certificado','certificate','Certificate / sanad','ser-tee-fee-kah-do','سرٹیفکیٹ'],['en regla','in order (documents valid)','Bilkul theek / mukammal','en reh-gla','بالکل درست'],['el plazo','deadline / time limit','Aakhri tareekh / muddat','plah-so','آخری تاریخ / مدت']],sents:[['Buenos días, tengo una cita a las diez para el visado.','Good morning, I have an appointment at ten for the visa.','Subah bakhair, meri das bajay visa ki appointment hai.'],['¿Qué documentos necesito para renovar el pasaporte?','What documents do I need to renew the passport?','Passport renew karwane ke liye kon se kagzaat chahiye?'],['He rellenado el formulario y traigo dos fotocopias.','I have filled in the form and I bring two photocopies.','Main ne form bhar liya hai aur do photocopies laya hoon.']],dlg:[['A','Buenos días. ¿En qué puedo ayudarle?','Good morning. How can I help you?'],['B','Buenos días. Vengo a pedir el visado. Tengo cita.','Good morning. I have come to apply for the visa. I have an appointment.'],['A','¿Ha rellenado el formulario? ¿Trae el pasaporte?','Have you filled in the form? Do you bring the passport?'],['B','Sí, todo en regla. ¿Cuánto tarda, más o menos?','Yes, everything in order. How long does it take, more or less?'],['A','Unas dos semanas. Le llamaremos.','About two weeks. We will call you.']],quiz:[['"La cita" at an embassy means...',['a party','an appointment','a city','a ticket'],1,'Cita = appointment (tay waqt).'],['"Rellenar el formulario" means...',['to sign the form','to fill in the form','to lose the form','to pay for the form'],1,'Rellenar = fill in (bharna).'],['"¿Cuánto tarda?" asks...',['How much does it cost?','How long does it take?','Where is it?','Who is it?'],1,'Tardar = to take (time). Cuesta = cost.'],['"El sello" is...',['the stamp / seal','the desk','the window','the queue'],0,'Sello = stamp (mohar).'],['Polite official talk uses...',['tú','usted','vosotros','yo'],1,'Usted = respect form for officials.']]},
{n:38,t:'Home Problems & Repairs',sub:'The tap leaks, the light fails — fix it in Spanish',ex:'When things break at home you need problem Spanish fast. Structure: "Hay un problema con..." (There is a problem with...) + the broken thing, or "No funciona..." (X does not work), "Está roto/a" (It is broken). Problems: la gotera (drip/leak), el grifo gotea (the tap drips), se fue la luz (the power went out), la tubería está rota (the pipe is broken), el enchufe no funciona (the socket does not work), hay humedad (there is damp). People: el fontanero (plumber), el electricista (electrician), el casero (landlord). Ask: "¿Cuándo puede venir?" (When can you come?) and "¿Cuánto costará la reparación?" (How much will the repair cost?).',words:[['no funciona','it does not work','Kaam nahi karta','no foon-see-oh-na','کام نہیں کرتا'],['está roto','it is broken','Toota hua hai','es-ta roh-to','ٹوٹا ہوا ہے'],['el grifo gotea','the tap drips / leaks','Nalka tapak raha hai','gree-fo goh-teh-a','نلکا ٹپک رہا ہے'],['se fue la luz','the power went out','Bijli chali gayi','seh fweh lah loos','بجلی چلی گئی'],['la tubería','pipe (water)','Paani ka pipe','too-beh-ree-a','پانی کا پائپ'],['el fontanero','plumber','Plumber / nal-saz','fon-tah-neh-ro','پلمبر'],['el electricista','electrician','Bijli wala / electrician','eh-lek-tree-sees-ta','بجلی والا'],['el casero','landlord','Malik-e-makan','kah-seh-ro','مالک مکان'],['¿cuándo puede venir?','when can you come?','Aap kab aa sakte hain?','kwan-do pweh-deh veh-neer','آپ کب آ سکتے ہیں؟'],['la reparación','the repair','Marammat','reh-pah-rah-see-on','مرمت'],['hay humedad','there is damp','Seelan hai','ay oo-meh-dad','سیلن ہے'],['una urgencia','an emergency (urgent job)','Fori kaam / emergency','oo-na oor-hen-see-a','فوری کام']],sents:[['Casero, hay un problema: el grifo gotea desde ayer.','Landlord, there is a problem: the tap has been dripping since yesterday.','Malik-e-makan, ek masla hai: nalka kal se tapak raha hai.'],['Se fue la luz en todo el piso anoche.','The power went out in the whole flat last night.','Kal raat pure flat ki bijli chali gayi thi.'],['¿Cuánto costará la reparación de la tubería?','How much will the pipe repair cost?','Pipe ki marammat par kitna kharcha hoga?']],dlg:[['A','¿Diga? Soy Farrakh, del piso tres.','Hello? I am Farrakh, from flat three.'],['B','Dígame, ¿qué pasa?','Tell me, what is the matter?'],['A','El grifo de la cocina gotea y hay humedad en la pared.','The kitchen tap drips and there is damp on the wall.'],['B','Mando al fontanero mañana. ¿Es una urgencia?','I will send the plumber tomorrow. Is it urgent?'],['A','No es urgente, pero gracias por venir rápido.','It is not urgent, but thanks for coming quickly.']],quiz:[['"Se fue la luz" means...',['The light is new','The power went out','Turn the light on','The lamp is broken'],1,'Irse la luz = power cut (bijli jana).'],['The plumber is...',['el electricista','el fontanero','el casero','el portero'],1,'Fontanero = plumber. Electricista = electrician.'],['"El grifo gotea" means...',['The tap is new','The tap drips','The tap is closed','The tap is hot'],1,'Gotear = to drip (tapakna).'],['Landlord in Spanish: ',['el inquilino','el vecino','el casero','el fontanero'],2,'Casero = landlord (malik-e-makan). Inquilino = tenant.'],['A fast polite opener for a home problem: ',['¡Rápido!','Hay un problema con...','Es tu culpa','Silencio'],1,'"Hay un problema con..." starts it calmly and clearly.']]},
{n:39,t:'Health Deep — Pharmacy & Symptoms',sub:'At the pharmacy: exactly what you need',ex:'At the pharmacy (la farmacia — look for the green cross), describe symptoms in detail: tengo tos seca (dry cough), me pica la garganta (my throat itches), tengo los ojos rojos (my eyes are red), estoy mareado (dizzy), tengo diarrea (diarrhoea), me torcí el tobillo (I twisted my ankle), tengo una herida (I have a wound/cut). Medicine words: las pastillas (tablets), el jarabe (syrup), la crema (cream/ointment), las gotas (drops), el termómetro (thermometer), una venda (bandage). Ask dosage clearly: "¿Cada cuántas horas?" (Every how many hours?) and "¿Antes o después de comer?" (Before or after eating?). Safety first: for real emergencies always say "¡Es urgente!" and ask for un médico.',words:[['la tos seca','dry cough','Khushk khansi','tos seh-ka','خشک کھانسی'],['me pica...','... itches me','Mujhe ... mein kharish hai','meh pee-ka','مجھے خارش ہے'],['estoy mareado','I feel dizzy','Mujhe chakkar aa rahe hain','es-toy mah-reh-ah-do','مجھے چکر آ رہے ہیں'],['me torcí el tobillo','I twisted my ankle','Mera takhna mur gaya','meh tor-see el toh-bee-yo','میرا ٹخنہ مڑ گیا'],['una herida','a wound / cut','Zakhm / cut','oo-na eh-ree-da','زخم'],['el jarabe','syrup (medicine)','Sharbat numa dawai / syrup','hah-rah-beh','شربت نما دوائی'],['las gotas','drops','Qatray','goh-tas','قطرے'],['la crema','cream / ointment','Cream / malam','kreh-ma','کریم / مرہم'],['¿cada cuántas horas?','every how many hours?','Har kitne ghantay baad?','kah-da kwan-tas oh-ras','ہر کتنے گھنٹے بعد؟'],['antes de comer','before eating','Khane se pehle','an-tes deh ko-mer','کھانے سے پہلے'],['sin receta','without prescription (over the counter)','Baghair nuskhay ke','seen reh-seh-ta','بغیر نسخے کے'],['¿tiene algo para...?','do you have something for...?','Kya aap ke paas ... ke liye kuch hai?','tee-eh-neh al-go pah-ra','کیا آپ کے پاس ۔۔۔ کے لیے کچھ ہے؟']],sents:[['¿Tiene algo para la tos seca? No puedo dormir.','Do you have something for a dry cough? I cannot sleep.','Kya khushk khansi ke liye kuch hai? Mujhe neend nahi aati.'],['Me torcí el tobillo jugando al fútbol ayer.','I twisted my ankle playing football yesterday.','Kal football khelte hue mera takhna mur gaya.'],['¿Cada cuántas horas tomo las pastillas?','Every how many hours do I take the tablets?','Main goliyan har kitne ghantay baad loon?']],dlg:[['A','Buenas tardes. ¿Tiene algo para el dolor de cabeza?','Good afternoon. Do you have something for a headache?'],['B','Sí. ¿Tiene fiebre también?','Yes. Do you have a fever too?'],['A','Un poco, y estoy mareado.','A little, and I feel dizzy.'],['B','Tome una pastilla cada ocho horas, después de comer. Y descanse.','Take one tablet every eight hours, after eating. And rest.'],['A','Muchas gracias. ¿Cuánto es?','Thank you very much. How much is it?']],quiz:[['"Estoy mareado" means...',['I am hungry','I feel dizzy','I am angry','I am late'],1,'Mareado = dizzy (chakkar).'],['Medicine syrup is...',['la crema','las gotas','el jarabe','la venda'],2,'Jarabe = syrup. Gotas = drops, crema = cream.'],['"¿Cada cuántas horas?" asks...',['How much does it cost?','Every how many hours?','How many tablets?','Is it serious?'],1,'Dosage question: every how many hours.'],['"Me pica la garganta" means...',['My throat hurts badly','My throat itches','I lost my voice','My throat is dry'],1,'Picar = to itch (kharish hona).'],['"Sin receta" medicines are...',['very strong','without prescription','for children','free'],1,'Sin receta = over the counter, no prescription needed.']]},
{n:40,t:'My Life Story',sub:'Past + future mixed — tell YOUR story',ex:'Your final B1 lesson mixes everything — because a real life story does. PAST for where you come from: "Nací en un pueblo de Punjab" (I was born in a village in Punjab), "De niño jugaba en los campos" (As a child I used to play in the fields), "Aprendí urdu en casa e inglés en la escuela". PRESENT for now: "Ahora aprendo español cada día". FUTURE for dreams: "Un día voy a viajar a España", "Espero trabajar con el español", "Quiero contar mi historia en español". Glue it with primero, luego, después, ahora, un día. Say your story aloud after this lesson — you finally CAN. ¡Enhorabuena, Farrakh — de A1 a B1!',words:[['nací en...','I was born in...','Main ... mein paida hua','nah-see en','میں ۔۔۔ میں پیدا ہوا'],['crecí en el pueblo','I grew up in the village','Main gaon mein bara hua','kreh-see en el pweh-blo','میں گاؤں میں بڑا ہوا'],['de niño jugaba...','as a child I used to play...','Bachpan mein main khela karta tha','deh neen-yo hoo-gah-ba','بچپن میں میں کھیلا کرتا تھا'],['fui a la escuela','I went to school','Main school gaya','fwee ah lah es-kweh-la','میں اسکول گیا'],['aprendí mucho','I learned a lot','Main ne bohat seekha','ah-pren-dee moo-cho','میں نے بہت سیکھا'],['mi vida cambió','my life changed','Meri zindagi badal gayi','mee vee-da kam-bee-oh','میری زندگی بدل گئی'],['ahora aprendo','now I am learning','Ab main seekh raha hoon','ah-oh-ra ah-pren-do','اب میں سیکھ رہا ہوں'],['trabajo y estudio','I work and I study','Main kaam aur parhai karta hoon','tra-bah-ho ee es-too-dee-oh','میں کام اور پڑھائی کرتا ہوں'],['un día viajaré','one day I will travel','Ek din main safar karunga','oon dee-a vee-ah-hah-reh','ایک دن میں سفر کروں گا'],['espero lograrlo','I hope to achieve it','Mujhe ummeed hai main kamiyab honga','es-peh-ro lo-grar-lo','مجھے امید ہے میں کامیاب ہوں گا'],['mi historia','my story','Meri kahani','mee ees-toh-ree-a','میری کہانی'],['¡sí se puede!','yes, it can be done!','Ho sakta hai!','see seh pweh-deh','ہو سکتا ہے!']],sents:[['Nací en Chak 18 Janoobi, un pueblo pequeño de Punjab, en Pakistán.','I was born in Chak 18 Janoobi, a small village in Punjab, Pakistan.','Main Pakistan ke Punjab ke chotay gaon Chak 18 Janoobi mein paida hua.'],['De niño jugaba en los campos y fui a la escuela del pueblo.','As a child I used to play in the fields and I went to the village school.','Bachpan mein main kheton mein khela karta tha aur gaon ke school gaya.'],['Un día voy a contar mi historia en España, en español.','One day I am going to tell my story in Spain, in Spanish.','Ek din main Spain mein, Spanish mein, apni kahani sunaunga.']],dlg:[['A','Cuéntame tu historia, Farrakh.','Tell me your story, Farrakh.'],['B','Nací en un pueblo de Pakistán. De niño, jugaba en los campos de trigo.','I was born in a village in Pakistan. As a child, I used to play in the wheat fields.'],['A','¿Y ahora?','And now?'],['B','Ahora aprendo español cada día, paso a paso.','Now I learn Spanish every day, step by step.'],['A','¿Y en el futuro?','And in the future?'],['B','Un día voy a viajar a España y contar mi historia allí. ¡Sí se puede!','One day I am going to travel to Spain and tell my story there. Yes, it can be done!']],quiz:[['"Nací en..." means...',['I live in...','I was born in...','I work in...','I study in...'],1,'Nacer = to be born: nací = I was born.'],['Which sentence is IMPERFECT (used to)?',['Ayer fui al mercado','De niño jugaba en el río','Mañana viajaré','Hoy estudio'],1,'Jugaba = used to play — childhood habit = imperfect.'],['"Un día viajaré" talks about...',['yesterday','now','the future','a habit'],2,'Viajaré = I will travel — true future tense!'],['"Mi vida cambió" means...',['My life is easy','My life changed','My life is long','My life starts'],1,'Cambiar = to change: cambió = it changed (preterite).'],['Your full story in order is...',['Future, past, present','Born (past) → learning (present) → dreams (future)','Only present','Only past'],1,'A life story: where you were born, what you do now, where you are going. ¡Eso es!']]}
);


/* ── LAYER 1 · CONTENT (continued) ── */
/* ============ LESSONS 41-50 (B2 PACK) ============ */
LESSONS.push(
{n:41,t:'Subjunctive — First Steps',sub:'Quiero que..., es importante que...',ex:'At B2 you meet the SUBJUNCTIVE — the verb form Spanish uses for wishes, hopes and advice about OTHER people. Formula: QUIERO QUE + subjunctive. The verb changes: hablar → hable, comer → coma, tener → tenga, ser → sea, estar → esté, ir → vaya, poder → pueda, saber → sepa. "Quiero que hables con él" (I want you to speak with him). "Es importante que descanses" (It is important that you rest). Use it when one person wants/influences another person.',words:[['Quiero que vengas','I want you to come','Main chahta hoon ke tum aao','kee-eh-ro keh ven-gas','میں چاہتا ہوں کہ تم آؤ'],['Es importante que estudies','It is important that you study','Zaroori hai ke tum parho','es eem-por-tan-teh keh es-too-dee-es','ضروری ہے کہ تم پڑھو'],['Espero que tengas suerte','I hope you are lucky','Umeed hai tumhari qismat achi ho','es-peh-ro keh ten-gas swer-teh','امید ہے تمہاری قسمت اچھی ہو'],['Te pido que me ayudes','I ask you to help me','Main tum se madad ki darkhwast karta hoon','teh pee-do keh meh ah-yoo-des','میں تم سے مدد کی درخواست کرتا ہوں'],['Ojalá pueda venir','Hopefully he can come','Kaash woh aa sake','oh-ha-la pwe-da veh-neer','کاش وہ آ سکے'],['Busco una casa que tenga jardín','I look for a house that has a garden','Main aisi house dhoond raha hoon jis mein bagh ho','boos-ko oo-na kah-sa keh ten-ga har-deen','میں ایسی گھر ڈھونڈ رہا ہوں جس میں باغ ہو'],['Es mejor que descansemos','It is better that we rest','Behtar hai ke hum aaram karein','es meh-hor keh des-kan-seh-mos','بہتر ہے کہ ہم آرام کریں'],['Quizás venga mañana','Maybe he will come tomorrow','Shayad woh kal aaye','kee-sas ven-ga man-yah-na','شاید وہ کل آئے'],['Dudo que sea verdad','I doubt it is true','Mujhe shak hai ke yeh sach ho','doo-do keh seh-ah ver-dad','مجھے شک ہے کہ یہ سچ ہو'],['Necesito que me llamen','I need them to call me','Mujhe chahiye ke woh mujhe call karein','neh-seh-see-to keh meh yah-men','مجھے چاہیے کہ وہ مجھے کال کریں'],['Antes de que salgas','Before you leave','Tumhare nikalne se pehle','an-tes deh keh sal-gas','تمہارے نکلنے سے پہلے']],sents:[['Quiero que me escuches con atención.','I want you to listen to me carefully.','Main chahta hoon ke tum tawajjo se suno.'],['Es importante que llegues a tiempo.','It is important that you arrive on time.','Zaroori hai ke tum waqt par pahoncho.'],['Espero que mi familia esté bien.','I hope my family is well.','Umeed hai mera khandan theek ho.']],dlg:[['A','Quiero que estudies español cada día.','I want you to study Spanish every day.'],['B','Lo sé. Es importante que practique mucho.','I know. It is important that I practise a lot.'],['A','Ojalá puedas viajar a España pronto.','Hopefully you can travel to Spain soon.'],['B','¡Y yo quiero que vengas conmigo!','And I want you to come with me!']],quiz:[['"Quiero que ___ conmigo" (venir, tú):',['vienes','vengas','venga','venir'],1,'After quiero que, tú venir → vengas (subjunctive).'],['"Es importante que ___ tiempo" (tener, nosotros):',['tenemos','tengamos','tienen','tener'],1,'Nosotros subjunctive of tener = tengamos.'],['Which sentence is a wish about another person?',['Yo estudio mucho','Quiero salir','Espero que tengas suerte','Tengo suerte'],2,'Espero que + subjunctive = hope about someone else.'],['Subjunctive of ser (yo/él) is...',['es','sea','sé','era'],1,'Ser → sea in the subjunctive.'],['"Ojalá ___ buen tiempo mañana" (hacer):',['hace','haga','hacemos','hacer'],1,'Ojalá always takes the subjunctive: haga.']]},
{n:42,t:'Conditional — Me gustaría…',sub:'I would like…, I would go…',ex:'The CONDITIONAL is the polite, dreamy tense: what you WOULD do. Take the whole infinitive and add -ía, -ías, -ía, -íamos, -íais, -ían: hablar → hablaría (I would speak). "Me gustaría viajar" (I would like to travel) — the most polite way to ask for anything. Irregulars change the stem: tener → tendría, poder → podría, hacer → haría, decir → diría, salir → saldría, querer → querría. Use it for wishes, polite requests and imaginary plans.',words:[['Me gustaría un té','I would like a tea','Mujhe ek chai chahiye (narmee se)','meh goos-tah-ree-ah oon teh','مجھے ایک چائے چاہیے'],['Viajaría a España','I would travel to Spain','Main Spain ka safar karta','vee-ah-hah-ree-ah ah es-pan-yah','میں سپین کا سفر کرتا'],['¿Podría ayudarme?','Could you help me?','Kya aap meri madad kar sakte hain?','po-dree-ah ah-yoo-dar-meh','کیا آپ میری مدد کر سکتے ہیں?'],['Sería perfecto','It would be perfect','Yeh bilkul perfect hota','seh-ree-ah per-fek-to','یہ بالکل پرفیکٹ ہوتا'],['Yo en tu lugar…','If I were you…','Main tumhari jagah hota to…','yo en too loo-gar','میں تمہاری جگہ ہوتا تو'],['Tendría que estudiar','I would have to study','Mujhe parhna parta','ten-dree-ah keh es-too-dee-ar','مجھے پڑھنا پڑتا'],['Nos encantaría','We would love it','Humein bohat pasand aata','nos en-kan-tah-ree-ah','ہمیں بہت پسند آتا'],['¿Te importaría…?','Would you mind…?','Kya tumhe aitraaz hoga…?','teh eem-por-tah-ree-ah','کیا تمہیں اعتراض ہوگا?'],['Con más dinero, compraría una casa','With more money, I would buy a house','Zyada paisy hotay to main ghar kharidta','kon mas dee-neh-ro kom-prah-ree-ah oo-na kah-sa','زیادہ پیسے ہوتے تو میں گھر خریدتا'],['Haríamos una fiesta','We would throw a party','Hum party karte','ah-ree-ah-mos oo-na fee-es-ta','ہم پارٹی کرتے'],['Vendría mañana','He would come tomorrow','Woh kal aata','ven-dree-ah man-yah-na','وہ کل آتا']],sents:[['Me gustaría hablar español sin miedo.','I would like to speak Spanish without fear.','Mujhe baghair dar ke Spanish bolna pasand aata.'],['Con tiempo, visitaría todo el país.','With time, I would visit the whole country.','Waqt hota to main poora mulk ghoomta.'],['¿Podría repetirlo, por favor?','Could you repeat it, please?','Kya aap dobara keh sakte hain?']],dlg:[['A','¿Qué harías con un millón de euros?','What would you do with a million euros?'],['B','Viajaría por España y compraría una casa pequeña.','I would travel around Spain and buy a small house.'],['A','Yo ayudaría a mi familia primero.','I would help my family first.'],['B','Eso sería lo mejor.','That would be the best thing.']],quiz:[['"I would like a coffee" politely:',['Quiero un café ahora','Me gustaría un café','Gustaría café yo','Yo gusto café'],1,'Me gustaría = I would like — the polite B2 form.'],['Conditional of hablar (yo):',['habló','hablaría','hablaba','hable'],1,'Infinitive + -ía = hablaría.'],['"¿___ ayudarme?" — most polite "Could you help me?":',['Puedes','Podría','Poder','Pudo'],1,'Podría = could (polite conditional).'],['Irregular conditional of tener (yo):',['tenería','tendría','tenga','tuve'],1,'Tener → tendr- + ía = tendría.'],['"Sería perfecto" means...',['It is perfect now','It was perfect','It would be perfect','Be perfect!'],2,'-ía endings talk about "would".']]},
{n:43,t:'Reported Speech',sub:'Dijo que… — telling what people said',ex:'To report what someone said, use DIJO QUE... (he/she said that...). "María dijo que estaba cansada" (María said that she was tired). Notice the verb steps BACK: es → era, está → estaba, quiero → quería, voy → iba, puedo → podía. For questions, report with SI: "Me preguntó si tenía tiempo" (He asked me if I had time). Commands become que + subjunctive: "Me dijo que esperara" (He told me to wait). This is how you tell stories about conversations.',words:[['Dijo que vendría','He said he would come','Us ne kaha ke woh aayega','dee-ho keh ven-dree-ah','اس نے کہا کہ وہ آئے گا'],['Me preguntó si…','He asked me if…','Us ne mujh se poocha ke kya…','meh preh-goon-to see','اس نے مجھ سے پوچھا کہ کیا'],['Contesté que sí','I answered yes','Main ne jawab diya ke haan','kon-tes-teh keh see','میں نے جواب دیا کہ ہاں'],['Explicó que no podía','He explained he could not','Us ne samjhaya ke woh nahi kar sakta tha','eks-plee-ko keh no po-dee-ah','اس نے سمجھایا کہ وہ نہیں کر سکتا تھا'],['Comentó que hacía frío','She mentioned it was cold','Us ne kaha ke sardi thi','ko-men-to keh ah-see-ah free-o','اس نے کہا کہ سردی تھی'],['Me pidió que esperara','He asked me to wait','Us ne mujh se intezaar karne ko kaha','meh pee-dee-o keh es-peh-rah-ra','اس نے مجھ سے انتظار کرنے کو کہا'],['Prometió que ayudaría','He promised he would help','Us ne wada kiya ke woh madad karega','pro-meh-tee-o keh ah-yoo-dah-ree-ah','اس نے وعدہ کیا کہ وہ مدد کرے گا'],['Pensé que era verdad','I thought it was true','Main samjha ke yeh sach tha','pen-seh keh eh-ra ver-dad','میں سمجھا کہ یہ سچ تھا'],['Según el médico…','According to the doctor…','Doctor ke mutabiq…','seh-goon el meh-dee-ko','ڈاکٹر کے مطابق'],['Resulta que…','It turns out that…','Pata chala ke…','reh-sool-ta keh','پتہ چلا کہ'],['Al parecer…','Apparently…','Zaahir hai ke…','al pah-reh-ser','ظاہر ہے کہ']],sents:[['Ahmed dijo que llegaría a las ocho.','Ahmed said he would arrive at eight.','Ahmed ne kaha ke woh aath bajay pahunchega.'],['Me preguntó si hablaba español.','He asked me if I spoke Spanish.','Us ne poocha ke kya main Spanish bolta hoon.'],['Ella contestó que estaba de acuerdo.','She answered that she agreed.','Us ne jawab diya ke woh muttafiq hai.']],dlg:[['A','¿Qué dijo el jefe?','What did the boss say?'],['B','Dijo que la reunión sería mañana.','He said the meeting would be tomorrow.'],['A','¿Y te preguntó algo?','And did he ask you something?'],['B','Sí, me preguntó si podía venir temprano.','Yes, he asked me if I could come early.']],quiz:[['"Dijo que ___ cansado" (he was tired):',['es','era','está','sea'],1,'Reported speech steps back: es → era.'],['Report: "Quiero té" → Él dijo que ___ té.',['quiero','quería','quiere','querría'],1,'Quiero steps back to quería.'],['"Me preguntó si ___ tiempo" (I had time):',['tengo','tenía','tener','tenga'],1,'After preguntó si, use imperfect: tenía.'],['"Me dijo que ___" for a command (esperar, tú → yo report):',['espera','esperara','esperas','esperar'],1,'Reported commands use que + subjunctive: esperara.'],['"Según el médico" means...',['Call the doctor','According to the doctor','The doctor said no','Near the doctor'],1,'Según = according to.']]},
{n:44,t:'Formal Letters & Emails',sub:'Estimado señor…, atentamente…',ex:'Formal writing in Spanish has fixed phrases — learn them once and reuse forever. Start: "Estimado señor García:" / "Estimada señora López:" (Dear Mr/Ms). Purpose: "Le escribo para…" (I am writing to you to…). Body requests are polite-conditional: "Le agradecería que…" (I would be grateful if you…). Close: "Quedo a la espera de su respuesta" (I await your reply), "Atentamente" (Sincerely), "Un cordial saludo" (Warm regards). Always use USTED in formal letters.',words:[['Estimado señor:','Dear Sir:','Mohtaram janab:','es-tee-mah-do sen-yor','محترم جناب'],['Le escribo para…','I am writing to you to…','Main aap ko … ke liye likh raha hoon','leh es-kree-bo pah-ra','میں آپ کو ...... کے لیے لکھ رہا ہوں'],['Me dirijo a usted para…','I am addressing you to…','Main aap se mukhatib hoon taake…','meh dee-ree-ho ah oos-ted pah-ra','میں آپ سے مخاطب ہوں تاکہ'],['Le agradecería que…','I would be grateful if you…','Main shukar guzaar honga agar aap…','leh ah-gra-deh-seh-ree-ah keh','میں شکر گزار ہوں گا اگر آپ'],['Adjunto mi currículum','I attach my CV','Main apna CV mansalik kar raha hoon','ad-hoon-to mee koo-ree-koo-loom','میں اپنا سی وی منسلک کر رہا ہوں'],['En relación con…','In relation to…','… ke silsilay mein','en reh-lah-see-on kon','...... کے سلسلے میں'],['Quedo a la espera de su respuesta','I await your reply','Main aap ke jawab ka muntazir hoon','keh-do ah la es-peh-ra deh soo res-pwes-ta','میں آپ کے جواب کا منتظر ہوں'],['Atentamente','Sincerely','Mukhlis','ah-ten-tah-men-teh','مخلص'],['Un cordial saludo','Warm regards','Neyk tamannayein','oon kor-dee-al sah-loo-do','نیک تمنائیں'],['Sin otro particular','With nothing further (closing)','Mazeed kuch khaas nahi','seen o-tro par-tee-koo-lar','مزید کچھ خاص نہیں'],['Distinguidos señores:','Dear Sirs (very formal):','Mohtaram hazraat:','dees-teen-gee-dos sen-yo-res','محترم حضرات']],sents:[['Le escribo para solicitar una cita.','I am writing to request an appointment.','Main appointment ki darkhwast ke liye likh raha hoon.'],['Le agradecería que me enviara la información.','I would be grateful if you sent me the information.','Main shukar guzaar honga agar aap maloomat bhej dein.'],['Atentamente, Farrakh.','Sincerely, Farrakh.','Mukhlis, Farrakh.']],dlg:[['A','¿Cómo empiezo un correo formal?','How do I start a formal email?'],['B','Con "Estimado señor" y dos puntos.','With "Dear Sir" and a colon.'],['A','¿Y cómo lo termino?','And how do I finish it?'],['B','Con "Atentamente" y tu nombre completo.','With "Sincerely" and your full name.']],quiz:[['A formal email to Mr. Pérez starts:',['Hola Pérez,','¡Qué tal, Pérez!','Estimado señor Pérez:','Querido amigo Pérez:'],2,'Formal = Estimado señor/señora + surname.'],['"Le escribo para…" means:',['I read to you','I am writing to you to…','Write to me','I wrote yesterday'],1,'Le escribo para + purpose is the classic formal opener.'],['Best closing for a formal letter:',['Un abrazo','Hasta luego','Atentamente','Nos vemos'],2,'Atentamente = Sincerely.'],['In formal letters you use:',['tú','usted','vosotros','amigo'],1,'Formal writing always uses usted.'],['"Adjunto mi CV" means:',['I lost my CV','I attach my CV','Delete my CV','My CV is old'],1,'Adjunto = I attach (in emails).']]},
{n:45,t:'Understanding the News',sub:'Titulares, según informa…, en directo',ex:'News Spanish uses a few special patterns. Headlines drop small words: "El gobierno anuncia nuevas medidas" (The government announces new measures). Common news verbs: anunciar (announce), confirmar (confirm), declarar (declare), aumentar (increase), reducir (reduce), ocurrir / suceder (happen), según (according to), mientras tanto (meanwhile), en directo (live), el titular (headline). The past in news is often the preterite: "Ayer ocurrió un accidente". Read the headline first — it holds the whole story.',words:[['el titular','headline','Surkhī / headline','tee-too-lar','سرخی'],['según informa…','according to reports…','Reports ke mutabiq…','seh-goon een-for-ma','رپورٹس کے مطابق'],['anunciar','to announce','Ailaan karna','ah-noon-see-ar','اعلان کرنا'],['aumentar','to increase','Barhna / barhana','ow-men-tar','بڑھنا'],['reducir','to reduce','Kam karna','reh-doo-seer','کم کرنا'],['ocurrir','to happen','Hona / waqea hona','oh-koo-reer','واقع ہونا'],['la medida','measure / step (policy)','Iqdam / pabandi','meh-dee-da','اقدام'],['el acuerdo','agreement','Muahida','ah-kwer-do','معاہدہ'],['en directo','live (broadcast)','Live / barah-e-raast','en dee-rek-to','لائیو'],['mientras tanto','meanwhile','Isi dauran','mee-en-tras tan-to','اسی دوران'],['la rueda de prensa','press conference','Press conference','rweh-da deh pren-sa','پریس کانفرنس']],sents:[['Según informa el periódico, habrá elecciones en mayo.','According to the newspaper, there will be elections in May.','Akhbar ke mutabiq, May mein elections honge.'],['Los precios han aumentado este mes.','Prices have increased this month.','Is mahinay qeematein barhi hain.'],['El accidente ocurrió ayer por la noche.','The accident happened last night.','Haadsa kal raat hua.']],dlg:[['A','¿Has visto las noticias?','Have you seen the news?'],['B','Sí. El titular dice que subirá el precio de la gasolina.','Yes. The headline says the price of petrol will rise.'],['A','¿Cuándo ocurrió?','When was it announced?'],['B','Lo anunciaron ayer en directo.','They announced it yesterday, live.']],quiz:[['"El titular" is...',['the teacher','the headline','the ticket','the title of a book only'],1,'Titular in news = headline.'],['"Mientras tanto" means...',['yesterday','meanwhile','suddenly','finally'],1,'Mientras tanto = meanwhile (isi dauran).'],['News verb "aumentar" =',['to fall','to happen','to increase','to announce'],2,'Aumentar = increase (barhna).'],['"En directo" means a broadcast is...',['recorded','live','cancelled','in English'],1,'En directo = live.'],['Headlines usually give the story in...',['long full sentences with every word','short form, small words dropped','questions only','the future tense only'],1,'Headlines drop small words like el/la to save space.']]},
{n:46,t:'Opinions, Debate & Arguing Politely',sub:'Estoy de acuerdo, pero…, en cambio…',ex:'Debating politely is a B2 superpower. Open softly: "Desde mi punto de vista…" (From my point of view…), "A mi parecer…" (In my view…). Disagree gently: "Entiendo tu punto, pero…" (I understand your point, but…), "No lo veo así" (I do not see it that way), "Respeto tu opinión, sin embargo…" (I respect your opinion, however…). Concede and counter: "Es cierto que…, pero en cambio…" (It is true that…, but on the other hand…). Close kindly: "En eso estamos de acuerdo" (On that we agree).',words:[['Desde mi punto de vista','From my point of view','Mere nuqta-e-nazar se','des-deh mee poon-to deh vees-ta','میرے نقطہ نظر سے'],['Entiendo tu punto, pero…','I understand your point, but…','Main tumhari baat samajhta hoon, lekin…','en-tee-en-do too poon-to peh-ro','میں تمہاری بات سمجھتا ہوں، لیکن'],['No lo veo así','I do not see it that way','Main isay aisay nahi dekhta','no lo veh-o ah-see','میں اسے ایسے نہیں دیکھتا'],['Es cierto que…, pero…','It is true that…, but…','Yeh sach hai ke…, lekin…','es see-er-to keh peh-ro','یہ سچ ہے کہ، لیکن'],['En cambio','On the other hand','Doosri taraf','en kam-bee-o','دوسری طرف'],['Por el contrario','On the contrary','Is ke bar-aks','por el kon-trah-ree-o','اس کے برعکس'],['A mi parecer','In my view','Mere khayal mein','ah mee pah-reh-ser','میرے خیال میں'],['Respeto tu opinión','I respect your opinion','Main tumhari raaye ka ehteraam karta hoon','res-peh-to too oh-pee-nee-on','میں تمہاری رائے کا احترام کرتا ہوں'],['Estamos de acuerdo en que…','We agree that…','Hum is par muttafiq hain ke…','es-tah-mos deh ah-kwer-do en keh','ہم اس پر متفق ہیں کہ'],['Depende de…','It depends on…','Yeh … par munhasir hai','deh-pen-deh deh','یہ ...... پر منحصر ہے'],['En conclusión','In conclusion','Khulasa yeh ke','en kon-kloo-see-on','خلاصہ یہ کہ']],sents:[['Desde mi punto de vista, aprender idiomas abre puertas.','From my point of view, learning languages opens doors.','Mere nuqta-e-nazar se, zabaanein seekhna darwazay kholta hai.'],['Es cierto que es difícil, pero en cambio es muy útil.','It is true that it is hard, but on the other hand it is very useful.','Yeh sach hai ke mushkil hai, lekin bohat faidamand hai.'],['En conclusión, depende de cada persona.','In conclusion, it depends on each person.','Khulasa, yeh har shakhs par munhasir hai.']],dlg:[['A','Creo que vivir en la ciudad es mejor.','I think living in the city is better.'],['B','Entiendo tu punto, pero yo prefiero el pueblo: es más tranquilo.','I understand your point, but I prefer the village: it is quieter.'],['A','Es cierto que el pueblo es tranquilo. En cambio, la ciudad tiene más trabajo.','It is true the village is quiet. On the other hand, the city has more work.'],['B','En eso estamos de acuerdo.','On that we agree.']],quiz:[['Softest way to disagree:',['¡No! ¡Nunca!','Entiendo tu punto, pero no lo veo así','Estás mal','Cállate'],1,'Acknowledge first, then disagree gently.'],['"En cambio" means...',['in change money','on the other hand','quickly','in the shop'],1,'En cambio = on the other hand.'],['"Es cierto que…" =',['It is a lie that','It is true that','I doubt that','Say that'],1,'Es cierto que = It is true that… (conceding).'],['"Depende de ti" means:',['It hangs from you','It depends on you','You decided','Ask you'],1,'Depende de = it depends on.'],['To close a debate politely:',['¡Yo gano!','En conclusión, respeto tu opinión','Nada más','Fin, adiós'],1,'Close kindly: conclusion + respect.']]},
{n:47,t:'Spanish for Work — Meetings & Calls',sub:'La reunión, el orden del día, quedamos en…',ex:'Work Spanish runs on meetings. Key phrases: "la reunión" (meeting), "el orden del día" (agenda), "el acta" (minutes/notes of the meeting), "quedar en…" (to agree on… — "Quedamos en vernos a las diez" = We agreed to meet at ten), "ponerse de acuerdo" (to reach agreement), "aplazar" (postpone), "adelantar" (bring forward), "¿A qué hora quedamos?" (What time shall we meet?). On calls: "Le paso con…" (I will put you through to…), "¿De parte de quién?" (Who is calling?).',words:[['el orden del día','agenda','Agenda / kaarwai ki list','or-den del dee-ah','ایجنڈا'],['el acta','minutes (of a meeting)','Meeting ki report','ak-ta','میٹنگ کی رپورٹ'],['Quedamos en vernos mañana','We agreed to meet tomorrow','Hum ne kal milne ka faisla kiya','keh-dah-mos en ver-nos man-yah-na','ہم نے کل ملنے کا فیصلہ کیا'],['ponerse de acuerdo','to reach agreement','Muttafiq hona','po-ner-seh deh ah-kwer-do','متفق ہونا'],['aplazar la reunión','to postpone the meeting','Meeting aagay barhana','ah-plah-sar la reh-oo-nee-on','میٹنگ آگے بڑھانا'],['Le paso con el director','I will put you through to the director','Main aap ki baat director se karwata hoon','leh pah-so kon el dee-rek-tor','میں آپ کی بات ڈائریکٹر سے کرواتا ہوں'],['¿De parte de quién?','Who is calling?','Aap kaun bol rahe hain?','deh par-teh deh kee-en','آپ کون بول رہے ہیں?'],['Tomar notas','To take notes','Notes likhna','to-mar no-tas','نوٹس لکھنا'],['El plazo termina el viernes','The deadline ends on Friday','Aakhri tareekh Jumma hai','el plah-so ter-mee-na el vee-er-nes','آخری تاریخ جمعہ ہے'],['Enviar el informe','To send the report','Report bhejna','en-vee-ar el een-for-meh','رپورٹ بھیجنا'],['¿A qué hora quedamos?','What time shall we meet?','Hum kis waqt milein?','ah keh oh-ra keh-dah-mos','ہم کس وقت ملیں?']],sents:[['Quedamos en terminar el informe el jueves.','We agreed to finish the report on Thursday.','Hum ne Jumeiraat tak report khatam karne ka faisla kiya.'],['El primer punto del orden del día es el presupuesto.','The first point on the agenda is the budget.','Agenda ka pehla point budget hai.'],['Le paso con la señora García.','I will put you through to Mrs García.','Main aap ki baat Mrs García se karwata hoon.']],dlg:[['A','¿A qué hora quedamos para la reunión?','What time shall we meet for the meeting?'],['B','A las diez. ¿Has visto el orden del día?','At ten. Have you seen the agenda?'],['A','Sí. Tenemos que terminar el informe hoy.','Yes. We have to finish the report today.'],['B','De acuerdo. Quedamos en eso.','Agreed. That is what we decided.']],quiz:[['"El orden del día" at a meeting is...',['lunch order','the agenda','the boss order','the minutes'],1,'Orden del día = agenda.'],['"Quedamos en vernos a las cinco" =',['We stayed until five','We agreed to meet at five','We saw five people','We left at five'],1,'Quedar en + verb = agree to do.'],['"Aplazar" a meeting means...',['hold it longer','postpone it','cancel forever','start it early'],1,'Aplazar = postpone (aagay barhana).'],['On the phone, "¿De parte de quién?" asks...',['What is the address?','Who is calling?','What time is it?','Where are you?'],1,'It is the polite "who is calling?".'],['"El acta" is...',['the actor','the meeting minutes','the agenda','the invitation'],1,'Acta = written minutes of the meeting.']]},
{n:48,t:'Culture, Festivals & Small Talk',sub:'La sobremesa, las fiestas, charlar…',ex:'Spanish culture has gifts for the learner. "La sobremesa" = the long chat at the table after eating — nobody rushes it. Festivals: "las Fallas" (Valencia, fire and figures in March), "la Tomatina" (tomato fight in Buñol), "San Fermín" (the running of the bulls in Pamplona), "la Semana Santa" (Holy Week processions). Small talk starters: "¿De dónde eres?" (Where are you from?), "¿A qué te dedicas?" (What do you do?), "¿Cuánto tiempo llevas aquí?" (How long have you been here?). Two kisses on the cheek are a normal greeting between friends in Spain — one is fine from you.',words:[['la sobremesa','after-meal table chat','Khanay ke baad ki lambi guftagu','so-breh-meh-sa','کھانے کے بعد کی لمبی گفتگو'],['la fiesta popular','local festival','Maquami mela / tehwaar','fee-es-ta po-poo-lar','مقامی میلہ'],['el ambiente','atmosphere / vibe','Mahol','am-bee-en-teh','ماحول'],['charlar','to chat','Gap shap karna','char-lar','گپ شپ کرنا'],['¡Qué interesante!','How interesting!','Kitna dilchasp!','keh een-teh-reh-san-teh','کتنا دلچسپ!'],['Cuéntame más','Tell me more','Mazeed batao','kwen-tah-meh mas','مزید بتاؤ'],['¿Cuánto tiempo llevas aquí?','How long have you been here?','Aap ko yahan kitna arsa hua?','kwan-to tee-em-po yeh-vas ah-kee','آپ کو یہاں کتنا عرصہ ہوا?'],['la costumbre','custom / habit','Riwaaj / aadat','kos-toom-breh','رواج'],['el anfitrión','host','Mezbaan','an-fee-tree-on','میزبان'],['Brindemos por…','Let us toast to…','Aao … ke naam par khushi manayein','breen-deh-mos por','آؤ خوشی منائیں'],['Pasarlo bien','To have a good time','Acha waqt guzaarna','pah-sar-lo bee-en','اچھا وقت گزارنا']],sents:[['En España, la sobremesa puede durar una hora.','In Spain, the after-meal chat can last an hour.','Spain mein khanay ke baad ki guftagu ek ghanta chal sakti hai.'],['Me encanta el ambiente de las fiestas del pueblo.','I love the atmosphere of the village festivals.','Mujhe gaon ke melo ka mahol bohat pasand hai.'],['¿Cuánto tiempo llevas en España?','How long have you been in Spain?','Aap ko Spain mein kitna arsa hua?']],dlg:[['A','¡Qué bien se está aquí! Me encanta el ambiente.','It is so nice here! I love the atmosphere.'],['B','Es la sobremesa — en mi casa nadie tiene prisa.','This is the sobremesa — in my house nobody is in a hurry.'],['A','Cuéntame: ¿cuál es la fiesta más famosa de tu pueblo?','Tell me: what is the most famous festival in your village?'],['B','La fiesta de agosto. ¡Tienes que venir!','The August festival. You have to come!']],quiz:[['"La sobremesa" is...',['the dessert','the long chat at the table after eating','the table itself','breakfast'],1,'Sobremesa = relaxed after-meal conversation.'],['"Charlar" means...',['to work','to chat','to cook','to travel'],1,'Charlar = chat (gap shap).'],['"¿Cuánto tiempo llevas aquí?" asks...',['What time is it?','How long have you been here?','How much does it cost?','When did you arrive today?'],1,'Llevar + time = how long you have been (doing).'],['"El ambiente" is...',['the ambulance','the atmosphere/vibe','the environment minister','the weather only'],1,'Ambiente = atmosphere, mahol.'],['A friendly small-talk question is:',['¿Cuánto dinero tienes?','¿De dónde eres?','¿Por qué llegas tarde?','¿Dónde está el baño?'],1,'¿De dónde eres? opens friendly conversation.']]},
{n:49,t:'If-Clauses',sub:'Si tengo tiempo…, si llueve…',ex:'IF-sentences (si clauses) follow one friendly pattern for real possibilities: SI + present, …future/present: "Si tengo tiempo, te llamo" (If I have time, I will call you). "Si llueve, nos quedamos en casa" (If it rains, we stay home). Never put "will" (futuro) right after si for real plans. For impossible dreams, Spanish uses a special past subjunctive — you will hear "Si tuviera dinero…" (If I had money…); recognise it now, and use the real pattern yourself: it covers almost everything you need to say.',words:[['Si tengo tiempo, te ayudo','If I have time, I will help you','Agar mere paas waqt hua to main madad karunga','see ten-go tee-em-po teh ah-yoo-do','اگر وقت ہوا تو مدد کروں گا'],['Si llueve, no salimos','If it rains, we will not go out','Agar barish hui to hum bahar nahi jayenge','see yweh-veh no sah-lee-mos','اگر بارش ہوئی تو ہم باہر نہیں جائیں گے'],['Si quieres, vamos ahora','If you want, let us go now','Agar tum chaho to abhi chalte hain','see kee-eh-res vah-mos ah-oh-ra','اگر چاہو تو ابھی چلتے ہیں'],['Si estudias, apruebas','If you study, you will pass','Agar parhoge to pass ho jaoge','see es-too-dee-as ah-prweh-bas','اگر پڑھو گے تو پاس ہو جاؤ گے'],['Si hace sol, iremos a la playa','If it is sunny, we will go to the beach','Agar dhoop hui to hum beach jayenge','see ah-seh sol ee-reh-mos ah la plah-yah','اگر دھوپ ہوئی تو ہم بیچ جائیں گے'],['Avísame si llegas tarde','Let me know if you arrive late','Agar dair ho to mujhe bata dena','ah-vee-sah-meh see yeh-gas tar-deh','اگر دیر ہو تو بتا دینا'],['Si tuviera dinero…','If I had money… (dream)','Kaash mere paas paisy hotay…','see too-vee-eh-ra dee-neh-ro','کاش میرے پاس پیسے ہوتے'],['En caso de que llueva','In case it rains','Agar barish ho jaye to','en kah-so deh keh yweh-vah','اگر بارش ہو جائے تو'],['Siempre que puedas','Whenever you can','Jab bhi tum kar sako','see-em-preh keh pweh-das','جب بھی تم کر سکو'],['Si no, no pasa nada','If not, no problem','Agar nahi, to koi baat nahi','see no no pah-sa nah-da','اگر نہیں تو کوئی بات نہیں'],['Depende de si viene','It depends on whether he comes','Yeh is par hai ke woh aata hai ya nahi','deh-pen-deh deh see vee-eh-neh','یہ اس پر ہے کہ وہ آتا ہے یا نہیں']],sents:[['Si termino temprano, te llamo.','If I finish early, I will call you.','Agar main jaldi farigh hua to call karunga.'],['Si no entiendes, pregúntame.','If you do not understand, ask me.','Agar samajh na aaye to mujh se poochna.'],['Si hace frío mañana, lleva el abrigo.','If it is cold tomorrow, take the coat.','Agar kal sardi ho to coat le lena.']],dlg:[['A','¿Vienes a la fiesta el sábado?','Are you coming to the party on Saturday?'],['B','Si termino el trabajo, sí.','If I finish work, yes.'],['A','Avísame si no puedes venir.','Let me know if you cannot come.'],['B','Claro. Y si llueve, ¿qué hacemos?','Of course. And if it rains, what do we do?'],['A','Si llueve, la hacemos en casa.','If it rains, we will do it at home.']],quiz:[['Correct real if-sentence:',['Si tendré tiempo, ayudo','Si tengo tiempo, te ayudo','Si tener tiempo, ayudo','Si yo teneré, ayudo'],1,'Real plans: si + present. No future right after si.'],['"Si llueve, nos quedamos" =',['If it rained yesterday','If it rains, we stay','It rains always','When it snowed'],1,'Llueve = it rains (present).'],['"Si tuviera dinero" expresses...',['a real plan for today','an impossible dream — "if I had money"','a past fact','a promise'],1,'Si tuviera… = imaginary "if I had…" — recognise it.'],['"Avísame si…" means:',['Warn me never','Let me know if…','Call me yesterday','Visit me if…'],1,'Avísame = let me know.'],['Complete: "Si estudias cada día, ___ mucho." (aprender)',['aprenderás','aprenderías ayer','aprendes ayer','aprendiste nunca'],0,'Si + present → future aprenderás works for real results.']]},
{n:50,t:'My Spanish Story — Full Review',sub:'Everything from 1 to 50, in your own story',ex:'Your final lesson is a full story that uses the whole path: greetings, ser and estar, past tenses, future plans, opinions, subjunctive wishes and if-clauses. Read it slowly, listen to every line, then answer the quiz — it samples the entire B2 level. After this quiz, take the B2 Final Exam from Practice. Then tell YOUR story: where you started (Lesson 1: "Hola"), and where you are now. ¡Enhorabuena, Farrakh — de A1 a B2!',words:[['al principio','at the beginning','Shuru mein','al preen-see-pee-o','شروع میں'],['poco a poco','little by little','Thora thora karke','po-ko ah po-ko','تھوڑا تھوڑا کرکے'],['sin parar','without stopping','Bina rukay','seen pah-rar','بنا رکے'],['al final','in the end','Aakhir mein','al fee-nal','آخر میں'],['valió la pena','it was worth it','Mehnat rang laayi','vah-lee-o la peh-na','محنت رنگ لائی'],['me siento capaz','I feel capable','Main khud ko qabil samajhta hoon','meh see-en-to kah-pas','میں خود کو قابل سمجھتا ہوں'],['contar mi historia','to tell my story','Apni kahani sunana','kon-tar mee ees-to-ree-ah','اپنی کہانی سنانا'],['un puente entre mundos','a bridge between worlds','Do duniyaon ke darmiyan pul','oon pwen-teh en-treh moon-dos','دو دنیاؤں کے درمیان پل'],['seguir aprendiendo','to keep learning','Seekhte rehna','seh-geer ah-pren-dee-en-do','سیکھتے رہنا'],['con confianza','with confidence','Aitemaad ke saath','kon kon-fee-an-sa','اعتماد کے ساتھ'],['lo logré','I achieved it / I did it','Main ne kar dikhaya','lo lo-greh','میں نے کر دکھایا']],sents:[['Al principio solo sabía decir "hola".','At the beginning I only knew how to say "hello".','Shuru mein mujhe sirf "hola" kehna aata tha.'],['Poco a poco aprendí a contar mi vida entera en español.','Little by little I learned to tell my whole life in Spanish.','Thora thora karke main ne apni poori zindagi Spanish mein sunana seekh liya.'],['Quiero que mi historia inspire a otros de mi pueblo.','I want my story to inspire others from my village.','Main chahta hoon ke meri kahani mere gaon ke doosron ko hosla de.']],dlg:[['A','Cuéntame tu historia con el español.','Tell me your story with Spanish.'],['B','Al principio era difícil. Pero estudié cada día, poco a poco.','At the beginning it was hard. But I studied every day, little by little.'],['A','¿Y ahora?','And now?'],['B','Ahora puedo trabajar, viajar y hacer amigos en español. ¡Lo logré!','Now I can work, travel and make friends in Spanish. I did it!']],quiz:[['"Valió la pena" means...',['It cost a lot','It was worth it','It hurt','It is a pity'],1,'Valer la pena = to be worth it.'],['Which sentence uses the subjunctive correctly?',['Quiero que vengas mañana','Quiero que vienes mañana','Quiero que venir mañana','Quiero vienes mañana'],0,'Quiero que + subjunctive: vengas.'],['"Si estudio cada día, hablaré mejor" is...',['wrong — future after si for plans','correct: si + present, then future','a reported command','past tense'],1,'Real if-pattern: si + present → future.'],['"Dijo que vendría" means:',['Say you will come','He said he would come','He came','Come here'],1,'Reported speech with conditional: vendría.'],['"Me gustaría seguir aprendiendo" =',['I liked learning','I would like to keep learning','I stopped learning','Learn more!'],1,'Me gustaría + infinitive = I would like to…']]}
);

export { LESSONS };
